sp_angular_provider.script:
[function () {
  'use strict';

  var THEME_KEY; // set by init()
  var appTheme;

  function systemPrefersDark() {
    return !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
  }
  function load(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; }
  }
  function save(key, value) {
    try { localStorage.setItem(key, value); } catch (e) {}
  }
  function applyApp() { document.documentElement.setAttribute('data-theme', appTheme); }

  var svc = {
    // Call once before use, with this app's own localStorage key prefix. A manual choice (stored)
    // always wins; with no stored choice yet, default to the OS/browser's prefers-color-scheme so
    // the app matches the system out of the box.
    init: function (keyPrefix) {
      THEME_KEY = keyPrefix + 'Theme';
      appTheme = load(THEME_KEY) || (systemPrefersDark() ? 'dark' : 'light');
      applyApp();
      return svc;
    },
    // A snapshot the controller mirrors onto vm after each mutation.
    readState: function () { return { theme: appTheme }; },
    toggleApp: function () {
      appTheme = appTheme === 'dark' ? 'light' : 'dark';
      save(THEME_KEY, appTheme);
      applyApp();
    },
  };
  return svc;
}]

function () {
  'use strict';

  var DOC = {
    "lead": "<p>The GlideFast scripting standards, in one place. Strong ServiceNow functionality begins with high-quality code: make it manageable, efficient, and scalable from the start, and you get better performance, fewer defects, and easier debugging. The practices below apply wherever you write server- or client-side script - Business Rules, Script Includes, Client Scripts, UI Actions, scheduled jobs, access controls, and beyond.</p>
<p>The code samples here are proven, real-world implementations, not illustrative pseudocode.</p>
<p><strong>Version 1.0 · Last reviewed 2026-07-15.</strong> Sections marked <strong>Extended guidance</strong> cover practices beyond GlideFast's original three source guides; everything else follows GlideFast's own guidance directly.</p>",
    "parts": [
      {
        "title": "Write Readable Code",
        "group": "Principles",
        "lead": "<p>Others will work with your code in the future. Always make it easy to read and understand, and follow your organization's formatting standards. What is obvious today is rarely obvious six months from now.</p>",
        "sections": [
          {
            "id": "comment-your-code",
            "title": "Comment Your Code",
            "html": "<h2 id="std-comment-your-code">Comment Your Code</h2>
<p>Comments should be as well-written and clear as the code they annotate. A single-line comment starts with <code>//</code>; everything after it to the end of the line is the comment:</p>
<pre class="std-pre"><code><span class="c-com">// a comment can sit on its own line, above the code it explains</span>
<span class="c-kw">var</span> count = <span class="c-num">0</span>;

count += batchSize; <span class="c-com">// or trail a statement, after the code on the same line</span></code></pre>
<p>A block comment runs from <code>/*</code> to <code>*/</code>. Use <a href="https://jsdoc.app/" target="_blank" rel="noopener">jsdoc</a> syntax to describe a function's purpose, inputs, and outputs:</p>
<pre class="std-pre"><code><span class="c-com">/**
 * Save a user preference for the current user. If the preference already exists, check the
 * current value and update it only if necessary.
 *
 * @param {string} preferenceName Name of the user preference.
 * @param {string} preferenceValue Value of the user preference.
 * @returns {boolean} True if the preference was updated, false if it was left unchanged.
 */</span></code></pre>
<p>Keep comments accurate and current - an out-of-date comment is worse than none, because it actively misleads. And write comments that add something. Restating the code teaches nothing:</p>
<pre class="std-pre"><code><span class="c-com">// unhelpful - the code already says this:</span>
<span class="c-com">// set i to 0</span>
<span class="c-kw">var</span> i = <span class="c-num">0</span>;

<span class="c-com">// helpful - explains intent that the code alone does not convey:</span>
<span class="c-com">// stop this record from ever reminding again</span>
recordGr.<span class="c-fn">setValue</span>(<span class="c-str">'return_reminder'</span>, <span class="c-kw">new</span> <span class="c-fn">GlideDateTime</span>());
recordGr.<span class="c-fn">update</span>();</code></pre>"
          },
          {
            "id": "use-white-space",
            "title": "Use White Space",
            "html": "<h2 id="std-use-white-space">Use White Space</h2>
<p>Empty lines and spaces make code readable, and readable code is easier to fix. Blank lines group related statements so the logical structure is visible; spaces within a line make the individual tokens legible. The <strong>Format Code</strong> button in the ServiceNow syntax editor adjusts indentation without disturbing your other spacing.</p>
<p>Cramped code hides its own logic:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">createRelationship</span>(typeId,childGr,parentGr){
<span class="c-kw">var</span> relationshipGr=<span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'cmdb_rel_ci'</span>);
<span class="c-kw">var</span> relationshipTypeGr=<span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'cmdb_rel_type'</span>);
<span class="c-kw">if</span>(childGr==parentGr)
<span class="c-kw">return</span>;
<span class="c-kw">if</span>(relationshipTypeGr.<span class="c-fn">get</span>(typeId)){
relationshipGr.<span class="c-fn">initialize</span>();
relationshipGr.<span class="c-fn">setValue</span>(<span class="c-str">'type'</span>,relationshipTypeGr.<span class="c-fn">getUniqueValue</span>());
relationshipGr.<span class="c-fn">setValue</span>(<span class="c-str">'child'</span>,childGr.<span class="c-fn">getValue</span>(<span class="c-str">'sys_id'</span>));
relationshipGr.<span class="c-fn">setValue</span>(<span class="c-str">'parent'</span>,parentGr.<span class="c-fn">getValue</span>(<span class="c-str">'sys_id'</span>));
relationshipGr.<span class="c-fn">insert</span>();
}
}</code></pre>
<p>A few spaces, blank lines, and consistent braces make the same logic obvious - and always wrap an <code>if</code> body in curly braces, even a one-liner:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">createRelationship</span>(typeId, childGr, parentGr) {
  <span class="c-kw">var</span> relationshipGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'cmdb_rel_ci'</span>);
  <span class="c-kw">var</span> relationshipTypeGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'cmdb_rel_type'</span>);

  <span class="c-kw">if</span> (childGr == parentGr) {
    <span class="c-kw">return</span>;
  }

  <span class="c-kw">if</span> (relationshipTypeGr.<span class="c-fn">get</span>(typeId)) {
    relationshipGr.<span class="c-fn">initialize</span>();

    relationshipGr.<span class="c-fn">setValue</span>(<span class="c-str">'type'</span>, relationshipTypeGr.<span class="c-fn">getUniqueValue</span>());
    relationshipGr.<span class="c-fn">setValue</span>(<span class="c-str">'child'</span>, childGr.<span class="c-fn">getUniqueValue</span>());
    relationshipGr.<span class="c-fn">setValue</span>(<span class="c-str">'parent'</span>, parentGr.<span class="c-fn">getUniqueValue</span>());

    <span class="c-kw">return</span> relationshipGr.<span class="c-fn">insert</span>();
  }
}</code></pre>"
          },
          {
            "id": "write-simple-statements",
            "title": "Write Simple Statements",
            "html": "<h2 id="std-write-simple-statements">Write Simple Statements</h2>
<p>Less experienced developers may maintain your code later, so favor clarity over cleverness - it is the engine's job to make code fast, not yours. An experienced developer reads a ternary without effort:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> result = x === y ? a : b;</code></pre>
<p>but the plain form is unambiguous for everyone:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> result;

<span class="c-kw">if</span> (x === y) {
  result = a;

} <span class="c-kw">else</span> {
  result = b;
}</code></pre>"
          },
          {
            "id": "use-descriptive-names",
            "title": "Use Descriptive Names",
            "html": "<h2 id="std-use-descriptive-names">Use Descriptive Names</h2>
<p>Meaningful names tell the reader what the code is for. This is impossible to follow:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">del</span>(r, d, s) {
  <span class="c-kw">var</span> a = <span class="c-num">0</span>;

  <span class="c-kw">if</span> (s === <span class="c-num">13</span>) { <span class="c-com">// 13 = cancelled</span>
    r.<span class="c-fn">deleteRecord</span>();

  } <span class="c-kw">else</span> {
    a = d;
  }

  <span class="c-kw">return</span> a;
}</code></pre>
<p>Rename everything for intent and it reads itself:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">deleteIfCanceled</span>(glideRecord, state, defaultAnswer) {
  <span class="c-kw">var</span> answer = <span class="c-num">0</span>;

  <span class="c-kw">if</span> (state === <span class="c-num">13</span>) { <span class="c-com">// 13 = cancelled</span>
    glideRecord.<span class="c-fn">deleteRecord</span>();

  } <span class="c-kw">else</span> {
    answer = defaultAnswer;
  }

  <span class="c-kw">return</span> answer;
}</code></pre>
<p>Short names are fine where convention makes them clear - <code>i</code> as a loop counter, for example:</p>
<pre class="std-pre"><code><span class="c-kw">for</span> (<span class="c-kw">var</span> i = <span class="c-num">0</span>; i &lt; list.length; i++) {
  <span class="c-com">// process each item</span>
}</code></pre>"
          },
          {
            "id": "store-repeated-results-in-a-variable",
            "title": "Store Repeated Results in a Variable",
            "html": "<h2 id="std-store-repeated-results-in-a-variable">Store Repeated Results in a Variable</h2>
<p>Avoid calling the same function repeatedly to get the same answer - it hurts both readability and, depending on the call, performance. Name the value once and reuse it:</p>
<pre class="std-pre"><code><span class="c-kw">if</span> (gs.<span class="c-fn">getUserID</span>() === current.<span class="c-fn">getValue</span>(<span class="c-str">'assigned_to'</span>) ||
  gs.<span class="c-fn">getUserID</span>() === current.<span class="c-fn">getValue</span>(<span class="c-str">'u_coordinator'</span>) ||
  gs.<span class="c-fn">getUserID</span>() === current.<span class="c-fn">getValue</span>(<span class="c-str">'caller_id'</span>)) {
    <span class="c-com">// do some processing here</span>
}</code></pre>
<p>reads far better as:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> currentUser = gs.<span class="c-fn">getUserID</span>();
<span class="c-kw">var</span> isOwner = currentUser === current.<span class="c-fn">getValue</span>(<span class="c-str">'assigned_to'</span>);
<span class="c-kw">var</span> isCoordinator = currentUser === current.<span class="c-fn">getValue</span>(<span class="c-str">'u_coordinator'</span>);
<span class="c-kw">var</span> isCaller = currentUser === current.<span class="c-fn">getValue</span>(<span class="c-str">'caller_id'</span>);

<span class="c-kw">if</span> (isOwner || isCoordinator || isCaller) {
  <span class="c-com">// do some processing here</span>
}</code></pre>"
          }
        ]
      },
      {
        "title": "Structure Code for Reuse",
        "group": "Principles",
        "lead": "<p>Break work into small, focused pieces. Small functions are easy to write, easy to understand, and easy to test - and easy for the next person to modify. As you build them, keep an eye on how the pieces fit: running the same query inside ten separate functions is a sign the shape is wrong.</p>",
        "sections": [
          {
            "id": "create-small-modular-components",
            "title": "Create Small, Modular Components",
            "html": "<h2 id="std-create-small-modular-components">Create Small, Modular Components</h2>
<p>When you see the same logic repeated, extract a function. It raises quality, saves you hunting through near-identical blocks when something breaks, and keeps the code maintainable. A Script Include is the natural home for that shared server-side logic - a library other server scripts call:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> IncidentService = Class.<span class="c-fn">create</span>();
IncidentService.prototype = {
    initialize: <span class="c-kw">function</span>() {
    },

    getIncident: <span class="c-kw">function</span>(sysId) {
        <span class="c-kw">var</span> incidentGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'incident'</span>);

        <span class="c-kw">if</span> (incidentGr.<span class="c-fn">get</span>(sysId)) {
            <span class="c-kw">return</span> incidentGr;
        }

        <span class="c-kw">return</span> <span class="c-kw">null</span>;
    },

    type: <span class="c-str">'IncidentService'</span>
};</code></pre>
<p>Suppose a process adds a user to one watch list, a different user to another, and a CI to a user-defined glide_list. Only the field and the element differ; the logic is identical. Write it once as <code>addGlideListElement(fieldValue, id)</code> and call it wherever you need it:</p>
<pre class="std-pre"><code>addGlideListElement: <span class="c-kw">function</span>(fieldValue, id) {
  <span class="c-kw">var</span> ids = [];

  <span class="c-kw">if</span> (fieldValue) {
    ids = fieldValue.<span class="c-fn">split</span>(<span class="c-str">','</span>);
  }

  <span class="c-kw">if</span> (ids.<span class="c-fn">indexOf</span>(id) === -<span class="c-num">1</span>) {
    ids.<span class="c-fn">push</span>(id);
  }

  <span class="c-kw">return</span> ids.<span class="c-fn">join</span>(<span class="c-str">','</span>);
}</code></pre>
<p>Then a Business Rule, workflow activity, or any other server script simply calls it:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> acmeIncident = <span class="c-kw">new</span> <span class="c-fn">AcmeIncident</span>();

<span class="c-kw">var</span> watchList = current.<span class="c-fn">getValue</span>(<span class="c-str">'watch_list'</span>);
<span class="c-kw">var</span> userId = gs.<span class="c-fn">getUserID</span>();

current.<span class="c-fn">setValue</span>(<span class="c-str">'watch_list'</span>, acmeIncident.<span class="c-fn">addGlideListElement</span>(watchList, userId));</code></pre>
<p>When you test a function, test both valid and invalid inputs so it holds up in the real world.</p>"
          },
          {
            "id": "wrap-code-in-a-function",
            "title": "Wrap Code in a Function",
            "html": "<h2 id="std-wrap-code-in-a-function">Wrap Code in a Function</h2>
<p>Code that is not enclosed in a function leaks its variables into the shared server- or client-side scope, where they can collide with variables of the same name in other scripts. Those collisions are painful to debug, because the usual tools point at the script producing the wrong result, not the script that leaked the global. Wrapping every script in a function makes the whole class of problem go away.</p>
<p>A Business Rule gives you the wrapper for free - keep it:</p>
<pre class="std-pre"><code>(<span class="c-kw">function</span> <span class="c-fn">executeRule</span>(current, previous) {
  <span class="c-kw">var</span> incidentGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'incident'</span>);

  incidentGr.<span class="c-fn">addQuery</span>(<span class="c-str">'active'</span>, <span class="c-kw">true</span>);
  incidentGr.<span class="c-fn">query</span>();

  <span class="c-kw">while</span> (incidentGr.<span class="c-fn">next</span>()) {
    <span class="c-com">// do some processing here</span>
  }
})(current, previous);</code></pre>
<p>Because <code>incidentGr</code> lives inside the function, no other script can see or clobber it. As added insurance, avoid the generic name <code>gr</code> entirely - a distinctive name makes a collision more remote still.</p>
<p>A Client Script is wrapped by default for the same reason. Declare your variables inside the handler, never outside it:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">onSubmit</span>() {
  <span class="c-kw">var</span> state = <span class="c-str">'6'</span>;

  <span class="c-kw">if</span> (g_form.<span class="c-fn">getValue</span>(<span class="c-str">'incident_state'</span>) === state) {
    <span class="c-fn">alert</span>(<span class="c-str">'This incident is Resolved'</span>);
  }
}</code></pre>
<p>For a script that only ever runs in one place - a transform map script, for instance - a self-executing function gives you the same isolation without a named, reusable definition. Inner functions declared inside it are private to it:</p>
<pre class="std-pre"><code>(<span class="c-kw">function</span> () {
  <span class="c-kw">function</span> <span class="c-fn">helperFunction</span>() {
    <span class="c-com">// return some value</span>
  }

  <span class="c-kw">var</span> value = <span class="c-fn">helperFunction</span>(); <span class="c-com">// valid - helperFunction is in scope here</span>
})();

<span class="c-kw">var</span> value2 = <span class="c-fn">helperFunction</span>(); <span class="c-com">// invalid - helperFunction is not visible out here</span></code></pre>"
          },
          {
            "id": "prefer-script-includes-to-global-scripts",
            "title": "Prefer Script Includes to Global Scripts",
            "html": "<h2 id="std-prefer-script-includes-to-global-scripts">Prefer Script Includes to Global Scripts</h2>
<p>A global script - a Business Rule or Client Script whose table is <strong>Global</strong> - loads on every page in the system, whether or not it is ever used there. Most such logic is narrow (an advanced reference qualifier on a single field, say), so loading it everywhere is pure overhead. A Script Include, by contrast, loads only when it is called.</p>
<p>If you have a global Business Rule, move its function into a Script Include of the same name; existing calls keep working unchanged. This global rule:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">backfillAssignmentGroup</span>() {
  <span class="c-kw">var</span> assignmentGroupIds = [];

  <span class="c-kw">var</span> assignedToId = current.<span class="c-fn">getValue</span>(<span class="c-str">'assigned_to'</span>);

  <span class="c-com">// return everything if the assigned_to value is empty</span>
  <span class="c-kw">if</span> (!assignedToId) {
    <span class="c-kw">return</span>;
  }

  <span class="c-com">// sys_user_grmember holds the user-to-group relationship</span>
  <span class="c-kw">var</span> groupMemberGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'sys_user_grmember'</span>);

  groupMemberGr.<span class="c-fn">addQuery</span>(<span class="c-str">'user'</span>, assignedToId);
  groupMemberGr.<span class="c-fn">query</span>();

  <span class="c-kw">while</span> (groupMemberGr.<span class="c-fn">next</span>()) {
    assignmentGroupIds.<span class="c-fn">push</span>(groupMemberGr.<span class="c-fn">getValue</span>(<span class="c-str">'group'</span>));
  }

  <span class="c-kw">return</span> <span class="c-str">'sys_idIN'</span> + assignmentGroupIds.<span class="c-fn">join</span>(<span class="c-str">','</span>);
}</code></pre>
<p>belongs in a Script Include:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> AssignmentGroup = Class.<span class="c-fn">create</span>();
AssignmentGroup.prototype = {
  initialize: <span class="c-kw">function</span>() {},

  backfillAssignmentGroup: <span class="c-kw">function</span>() {
    <span class="c-kw">var</span> assignmentGroupIds = [];

    <span class="c-kw">var</span> assignedToId = current.<span class="c-fn">getValue</span>(<span class="c-str">'assigned_to'</span>);

    <span class="c-kw">if</span> (!assignedToId) {
      <span class="c-kw">return</span>;
    }

    <span class="c-kw">var</span> groupMemberGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'sys_user_grmember'</span>);

    groupMemberGr.<span class="c-fn">addQuery</span>(<span class="c-str">'user'</span>, assignedToId);
    groupMemberGr.<span class="c-fn">query</span>();

    <span class="c-kw">while</span> (groupMemberGr.<span class="c-fn">next</span>()) {
      assignmentGroupIds.<span class="c-fn">push</span>(groupMemberGr.<span class="c-fn">getValue</span>(<span class="c-str">'group'</span>));
    }

    <span class="c-kw">return</span> <span class="c-str">'sys_idIN'</span> + assignmentGroupIds.<span class="c-fn">join</span>(<span class="c-str">','</span>);
  },

  type: <span class="c-str">'AssignmentGroup'</span>
};</code></pre>
<p>The same reasoning applies on the client. Rather than a global Client Script, move field logic onto a base table such as Task or Configuration Item, where the extending tables inherit it - so it loads on those forms instead of every home page and catalog item in the instance.</p>"
          }
        ]
      },
      {
        "title": "Work with Data Efficiently",
        "group": "Principles",
        "lead": "<p>Every database interaction has a cost, and that cost grows as your instance does. Lean on the database to do the heavy lifting, and never fetch more than you need.</p>",
        "sections": [
          {
            "id": "avoid-complex-gliderecord-queries",
            "title": "Avoid Complex GlideRecord Queries",
            "html": "<h2 id="std-avoid-complex-gliderecord-queries">Avoid Complex GlideRecord Queries</h2>
<p>Rather than assembling a result with a chain of <code>addQuery()</code> and <code>addOrCondition()</code> calls, build an encoded query and pass it to <code>addEncodedQuery()</code>. Consider "all active Apple printers and computers in the Santa Ana office." The chained-condition version is fiddly to get right - and the moment the requirement changes (another location, another manufacturer), it becomes hard to maintain.</p>
<p>Instead, build the filter in a list, copy its encoded query string, and use that. When the requirement changes, rebuild the filter, confirm the results with whoever owns the requirement, and drop the new string into the same script.</p>"
          },
          {
            "id": "prefer-glidequery-for-clear-safe-queries",
            "title": "Prefer GlideQuery for Clear, Safe Queries",
            "html": "<h2 id="std-prefer-glidequery-for-clear-safe-queries">Prefer GlideQuery for Clear, Safe Queries <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>GlideQuery is a modern, fluent wrapper over the database that reads top to bottom as a single sentence and fails loudly when something is wrong. The same "get one incident, guard the result" shape you would build with GlideRecord becomes:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> incident = <span class="c-kw">new</span> <span class="c-fn">GlideQuery</span>(<span class="c-str">'incident'</span>)
  .<span class="c-fn">where</span>(<span class="c-str">'sys_id'</span>, sysId)
  .<span class="c-fn">selectOne</span>(<span class="c-str">'number'</span>, <span class="c-str">'priority'</span>)
  .<span class="c-fn">orElse</span>(<span class="c-kw">null</span>);

<span class="c-kw">if</span> (incident) {
  <span class="c-com">// incident is a plain object - { sys_id, number, priority } - already narrowed to the fields you asked for</span>
}</code></pre>
<p>Two things make it safer than a hand-written GlideRecord loop. It is <strong>null-safe</strong>: <code>selectOne</code> returns an Optional, so you have to decide what happens when nothing matches (<code>orElse</code>) instead of forgetting the <code>if (gr.next())</code> guard. And it is <strong>strict</strong>: a mistyped field name throws immediately, where <code>gr.getValue('piority')</code> would hand back an empty string and send you hunting for the bug later.</p>
<p>It counts and aggregates too, so it can stand in for many GlideRecord and GlideAggregate patterns:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> activeCount = <span class="c-kw">new</span> <span class="c-fn">GlideQuery</span>(<span class="c-str">'incident'</span>)
  .<span class="c-fn">where</span>(<span class="c-str">'active'</span>, <span class="c-kw">true</span>)
  .<span class="c-fn">count</span>();</code></pre>
<p>Reach for GlideQuery for the everyday reads, writes, and counts in new code. GlideRecord is still the right tool when you are streaming a very large result set or need an API GlideQuery does not wrap - and the GlideRecord guidance above (guard the result, cap what you return, name the variable well) applies to GlideQuery just the same.</p>"
          },
          {
            "id": "use-glideaggregate-for-simple-record-counting",
            "title": "Use GlideAggregate for Simple Record Counting",
            "html": "<h2 id="std-use-glideaggregate-for-simple-record-counting">Use GlideAggregate for Simple Record Counting</h2>
<p>To count rows you have two options: <code>getRowCount()</code> on a GlideRecord, or GlideAggregate. GlideRecord retrieves every matching record and then counts them, which does not scale as the table grows. GlideAggregate asks the database to count, which is fast and scales cleanly. Prefer it:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">getIncidentCount</span>(encodedQuery) {
  <span class="c-kw">var</span> incidentGa = <span class="c-kw">new</span> <span class="c-fn">GlideAggregate</span>(<span class="c-str">'incident'</span>);

  incidentGa.<span class="c-fn">addEncodedQuery</span>(encodedQuery);
  incidentGa.<span class="c-fn">addAggregate</span>(<span class="c-str">'COUNT'</span>);
  incidentGa.<span class="c-fn">query</span>();

  <span class="c-kw">if</span> (incidentGa.<span class="c-fn">next</span>()) {
    <span class="c-kw">return</span> <span class="c-fn">parseInt</span>(incidentGa.<span class="c-fn">getAggregate</span>(<span class="c-str">'COUNT'</span>), <span class="c-num">10</span>);
  }

  <span class="c-kw">return</span> <span class="c-num">0</span>;
}</code></pre>"
          },
          {
            "id": "let-the-database-do-the-work",
            "title": "Let the Database Do the Work",
            "html": "<h2 id="std-let-the-database-do-the-work">Let the Database Do the Work</h2>
<p>Whenever you can, let the database return exactly the records you need. To check whether <em>at least one</em> active incident exists, a first attempt might query them all:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> incidentGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'incident'</span>);

incidentGr.<span class="c-fn">addQuery</span>(<span class="c-str">'active'</span>, <span class="c-kw">true</span>);
incidentGr.<span class="c-fn">query</span>();

<span class="c-kw">if</span> (incidentGr.<span class="c-fn">hasNext</span>()) {
  <span class="c-com">// there is at least one active record</span>
}</code></pre>
<p>If there are 250,000 active records, <code>query()</code> retrieves all of them. Ask the database for one instead - it is far faster:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> incidentGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'incident'</span>);

incidentGr.<span class="c-fn">addQuery</span>(<span class="c-str">'active'</span>, <span class="c-kw">true</span>);
incidentGr.<span class="c-fn">setLimit</span>(<span class="c-num">1</span>); <span class="c-com">// return at most one record</span>
incidentGr.<span class="c-fn">query</span>();

<span class="c-kw">if</span> (incidentGr.<span class="c-fn">hasNext</span>()) {
  <span class="c-com">// there is at least one active record</span>
}</code></pre>"
          },
          {
            "id": "avoid-complex-queries-on-large-data-sets",
            "title": "Avoid Complex Queries on Large Data Sets",
            "html": "<h2 id="std-avoid-complex-queries-on-large-data-sets">Avoid Complex Queries on Large Data Sets</h2>
<p>Limit how often you search large tables; as the instance grows, those searches degrade performance. Imagine needing the importance of every upstream service related to a server whenever that server is added to an incident. On a small CMDB, querying the Relationship [cmdb_rel_ci] table is fine. On a CMDB with three million CIs and hundreds of thousands of relationships, that query could take hours.</p>
<p>A better design precomputes the answer: maintain a related list of affected services on the CI, updated by a Business Rule as relationships change. When the CI is added to an incident, read the short related list instead of launching a long search across the relationship table.</p>"
          },
          {
            "id": "minimize-server-lookups",
            "title": "Minimize Server Lookups",
            "html": "<h2 id="std-minimize-server-lookups">Minimize Server Lookups</h2>
<p>Client code runs on data already on the form or data fetched from the server; use what is already there whenever you can, because server round trips are slow. The two efficient ways to pull from the server are <code>g_scratchpad</code> (pushed once, when the form loads) and an asynchronous GlideAjax call (requested on demand). Older approaches - <code>GlideRecord</code> on the client and <code>g_form.getReference()</code> - are no longer recommended: they fetch every field when you usually need one, and the client-side GlideRecord API is unavailable in scoped applications.</p>
<p>When you know before load what the client will need, a display Business Rule can stage it in <code>g_scratchpad</code>:</p>
<pre class="std-pre"><code>g_scratchpad.css = gs.<span class="c-fn">getProperty</span>(<span class="c-str">'css.base.color'</span>);
g_scratchpad.hasAttachments = current.<span class="c-fn">hasAttachments</span>();
g_scratchpad.managerName = current.caller_id.manager.<span class="c-fn">getDisplayValue</span>();</code></pre>
<p>When the need arises dynamically, call a client-callable Script Include asynchronously. Always use the asynchronous <code>getXMLAnswer()</code>, never a synchronous call. This is the client half of that call:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">getIncident</span>(sysId, callback) {
  <span class="c-kw">var</span> incidentServiceAjax = <span class="c-kw">new</span> <span class="c-fn">GlideAjax</span>(<span class="c-str">'IncidentService'</span>);

  incidentServiceAjax.<span class="c-fn">addParam</span>(<span class="c-str">'sysparm_name'</span>, <span class="c-str">'getIncident'</span>);
  incidentServiceAjax.<span class="c-fn">addParam</span>(<span class="c-str">'sysparm_sys_id'</span>, sysId);

  incidentServiceAjax.<span class="c-fn">getXMLAnswer</span>(<span class="c-kw">function</span> (response) {
    <span class="c-fn">callback</span>(response ? JSON.<span class="c-fn">parse</span>(response) : <span class="c-kw">null</span>);
  });
}</code></pre>
<p>backed by an <code>AbstractAjaxProcessor</code> Script Include on the server:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> ConfigurationItem = Class.<span class="c-fn">create</span>();
ConfigurationItem.prototype = Object.<span class="c-fn">extendsObject</span>(AbstractAjaxProcessor, {
  getSupportGroup: <span class="c-kw">function</span>() {
    <span class="c-kw">var</span> configurationItemId = this.<span class="c-fn">getParameter</span>(<span class="c-str">'sysparm_configuration_item_id'</span>);
    <span class="c-kw">var</span> assignmentGroupId = this.<span class="c-fn">getParameter</span>(<span class="c-str">'sysparm_assignment_group_id'</span>);

    <span class="c-kw">var</span> configurationItemGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'cmdb_ci'</span>);

    <span class="c-kw">if</span> (configurationItemGr.<span class="c-fn">get</span>(configurationItemId)) {
      <span class="c-kw">if</span> (configurationItemGr.<span class="c-fn">getValue</span>(<span class="c-str">'support_group'</span>) === assignmentGroupId) {
        <span class="c-kw">return</span> <span class="c-str">'CI support group and assignment group match'</span>;
      }
    }

    <span class="c-kw">return</span> <span class="c-str">'CI support group and assignment group do not match'</span>;
  }
});</code></pre>
<p>One more round trip worth avoiding: when you <code>setValue()</code> a reference field, pass the display value alongside the sys_id. Without it, the client makes a synchronous call back to the server just to resolve the label:</p>
<pre class="std-pre"><code><span class="c-com">// causes a synchronous server call to fetch the display value:</span>
g_form.<span class="c-fn">setValue</span>(<span class="c-str">'assigned_to'</span>, assignedToId);

<span class="c-com">// no server call - the display value is supplied:</span>
g_form.<span class="c-fn">setValue</span>(<span class="c-str">'assigned_to'</span>, assignedToId, assignedToName);</code></pre>"
          }
        ]
      },
      {
        "title": "Code Defensively",
        "group": "Principles",
        "lead": "<p>Assume inputs can be missing or wrong, and assume the state of the world can change between two lines of your script. Defensive code fails safely instead of silently.</p>",
        "sections": [
          {
            "id": "verify-values-exist-before-using-them",
            "title": "Verify Values Exist Before Using Them",
            "html": "<h2 id="std-verify-values-exist-before-using-them">Verify Values Exist Before Using Them</h2>
<p>Check that a variable or field has a value before you use it, or you risk unpredictable results and log warnings:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> table = current.<span class="c-fn">getTableName</span>();

<span class="c-kw">if</span> (table) {
  gs.<span class="c-fn">print</span>(<span class="c-str">'Table is: '</span> + table);

} <span class="c-kw">else</span> {
  gs.<span class="c-fn">print</span>(<span class="c-str">'Warning: table is undefined'</span>);
}</code></pre>"
          },
          {
            "id": "return-a-meaningful-value",
            "title": "Return a Meaningful Value",
            "html": "<h2 id="std-return-a-meaningful-value">Return a Meaningful Value</h2>
<p>Get in the habit of returning something from every function you write - the return value tells the caller how the call went. Common conventions are a count (0 to signal an error), a success flag (true for success), or an object (null for failure):</p>
<pre class="std-pre"><code><span class="c-kw">if</span> (!<span class="c-fn">saveRecord</span>(current)) {
  gs.<span class="c-fn">addErrorMessage</span>(<span class="c-str">'Save Error'</span>);
}

<span class="c-kw">function</span> <span class="c-fn">saveRecord</span>(glideRecord) {
  <span class="c-kw">var</span> recordId = glideRecord.<span class="c-fn">update</span>();

  <span class="c-kw">if</span> (!recordId.<span class="c-fn">nil</span>()) {
    <span class="c-kw">return</span> <span class="c-kw">true</span>;
  }

  <span class="c-kw">return</span> <span class="c-kw">false</span>;
}</code></pre>"
          },
          {
            "id": "handle-errors-gracefully",
            "title": "Handle Errors Gracefully",
            "html": "<h2 id="std-handle-errors-gracefully">Handle Errors Gracefully</h2>
<p>Some operations can fail at runtime through no fault of your logic - parsing a string that turns out not to be valid JSON, calling an integration that times out, reading a record on a table a plugin never activated. An unhandled failure aborts the whole transaction, and the user gets a stack trace instead of a useful message. Wrap the operation that can realistically fail in a <code>try</code>/<code>catch</code>, log the error with enough context to find it, and fail safely:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">getRequestPayload</span>(jsonString) {
  try {
    <span class="c-kw">return</span> JSON.<span class="c-fn">parse</span>(jsonString);

  } catch (e) {
    <span class="c-com">// log with context so the failure is findable, then fail safely</span>
    gs.<span class="c-fn">error</span>(<span class="c-str">'getRequestPayload: could not parse payload - '</span> + e.message);
    <span class="c-kw">return</span> <span class="c-kw">null</span>;
  }
}</code></pre>
<p>Wrap the specific risky call, not the whole script - a blanket <code>try</code>/<code>catch</code> around everything hides the ordinary bugs you <em>want</em> to fail loudly while you are still developing. And always do something in the <code>catch</code>: an empty catch block swallows the problem and leaves you debugging a symptom far from its cause. This is the shape to follow - a <code>try</code>/<code>catch</code> that logs with <code>gs.error</code>.</p>"
          },
          {
            "id": "log-at-the-right-level",
            "title": "Log at the Right Level",
            "html": "<h2 id="std-log-at-the-right-level">Log at the Right Level</h2>
<p>ServiceNow gives you leveled logging - <code>gs.info</code>, <code>gs.warn</code>, and <code>gs.error</code> - and each entry is tagged with its source and filterable by level in the system log. Match the level to the severity: <code>gs.error</code> for a genuine failure, <code>gs.warn</code> for a recoverable oddity worth noticing, <code>gs.info</code> for a milestone. The older <code>gs.log()</code> and <code>gs.print()</code> are global-scope holdovers - <code>gs.print</code> in particular writes only to background-script and node output, not the system log - so keep them for ad-hoc testing and reach for the leveled methods in code you ship.</p>
<p>Log something you could actually debug from - carry the values that would let you reconstruct what happened, not a bare marker:</p>
<pre class="std-pre"><code><span class="c-com">// unhelpful - tells you it ran, nothing more:</span>
gs.<span class="c-fn">info</span>(<span class="c-str">'here'</span>);

<span class="c-com">// helpful - carries the context you would need to trace a problem:</span>
gs.<span class="c-fn">info</span>(<span class="c-str">'AssignmentGroup: no group found for user '</span> + assignedToId);</code></pre>
<p>Verbose tracing is invaluable during an incident and pure noise the rest of the time. Gate it behind a system property so you can switch it on without a code change, and leave it off by default:</p>
<pre class="std-pre"><code><span class="c-kw">if</span> (gs.<span class="c-fn">getProperty</span>(<span class="c-str">'acme.debug'</span>) === <span class="c-str">'true'</span>) {
  gs.<span class="c-fn">info</span>(<span class="c-str">'AssignmentGroup: resolved group to '</span> + groupId);
}</code></pre>"
          },
          {
            "id": "double-check-critical-input-on-the-server",
            "title": "Double-Check Critical Input on the Server",
            "html": "<h2 id="std-double-check-critical-input-on-the-server">Double-Check Critical Input on the Server</h2>
<p>A Client Script validating input is good for the user - they learn about a problem before submitting. In this example, Low impact is not allowed with High priority:</p>
<pre class="std-pre"><code><span class="c-kw">if</span> (g_form.<span class="c-fn">getValue</span>(<span class="c-str">'impact'</span>) === <span class="c-str">'3'</span> &amp;&amp; g_form.<span class="c-fn">getValue</span>(<span class="c-str">'priority'</span>) === <span class="c-str">'1'</span>) {
  g_form.<span class="c-fn">showErrorBox</span>(<span class="c-str">'impact'</span>, <span class="c-str">'Low impact not allowed with High priority'</span>);
}</code></pre>
<p>But client-side validation is not enough on its own, because data can change between the moment the form is filled in and the moment it is submitted. Suppose a request lets users reserve items, showing only available ones. Two people open the form at the same time and both pick the same item - it still looks available to each, because neither has submitted. Re-check the critical condition in a Business Rule at submit time so the second request is caught:</p>
<pre class="std-pre"><code>(<span class="c-kw">function</span> <span class="c-fn">executeRule</span>(current, previous) {
  <span class="c-fn">isCiAvailable</span>();

  <span class="c-kw">function</span> <span class="c-fn">isCiAvailable</span>() {
    <span class="c-kw">var</span> loanerUtils = <span class="c-kw">new</span> <span class="c-fn">LoanerUtils</span>();

    <span class="c-kw">if</span> (!loanerUtils.<span class="c-fn">isAvailable</span>(current.cmdb_ci, current.start_date, current.end_date)) {
      gs.<span class="c-fn">addErrorMessage</span>(gs.<span class="c-fn">getMessage</span>(<span class="c-str">'Sorry, that item has already been allocated'</span>));

      current.<span class="c-fn">setValue</span>(<span class="c-str">'cmdb_ci'</span>, <span class="c-str">'NULL'</span>);
    }
  }
})(current, previous);</code></pre>"
          },
          {
            "id": "prevent-recursive-updates",
            "title": "Prevent Recursive Updates",
            "html": "<h2 id="std-prevent-recursive-updates">Prevent Recursive Updates</h2>
<p>Never call <code>current.update()</code> in a Business Rule. <code>update()</code> fires the insert/update Business Rules on the same table again, which can make a rule call itself indefinitely. Changes made in a before rule are saved automatically once all before rules finish, and after rules should update related records, not the current one - so <code>current.update()</code> is never needed under normal guidelines. ServiceNow will detect and stop a recursive rule and log the error, but it costs performance you do not need to spend.</p>
<p>If a rare requirement genuinely needs an update outside those guidelines, pair it with <code>current.setWorkflow(false)</code> to stop Business Rules and related engines from running on that write and breaking the cycle.</p>"
          },
          {
            "id": "avoid-the-eval-function",
            "title": "Avoid the eval() Function",
            "html": "<h2 id="std-avoid-the-eval-function">Avoid the eval() Function</h2>
<p><code>eval()</code> executes whatever string you hand it, which opens the door to injection and makes debugging harder - errors carry no line numbers. Where you must evaluate a string, use the platform API instead:</p>
<pre class="std-pre"><code>GlideEvaluator.<span class="c-fn">evaluateString</span>(<span class="c-str">'gs.log(\'Hello World\');'</span>);</code></pre>"
          }
        ]
      },
      {
        "title": "Control When Code Runs",
        "group": "Principles",
        "lead": "<p>Code that runs when it does not need to is wasted work - and on a form or a busy table, wasted work the user feels. Run logic only when its conditions are actually met.</p>",
        "sections": [
          {
            "id": "choose-the-right-business-rule-timing",
            "title": "Choose the Right Business Rule Timing",
            "html": "<h2 id="std-choose-the-right-business-rule-timing">Choose the Right Business Rule Timing</h2>
<p>The <strong>When</strong> value decides whether a Business Rule runs before or after the record is written. Match it to what the rule does:</p>
<table class="std-table"><thead><tr><th>Value</th><th>Use it to</th></tr></thead><tbody><tr><td>display</td><td>Give client-side scripts access to server-side data (via <code>g_scratchpad</code>).</td></tr><tr><td>before</td><td>Update fields on the current record - e.g. <code>current.setValue('state', 3);</code> before it is saved.</td></tr><tr><td>after</td><td>Update related records that must be visible immediately.</td></tr><tr><td>async</td><td>Update related records that can wait - metrics, SLAs - so control returns to the user sooner.</td></tr></tbody></table>
<p>An async rule is like an after rule but runs in the background after the commit; it frees the user sooner at the cost of updating related objects slightly later.</p>"
          },
          {
            "id": "order-business-rules-and-client-scripts",
            "title": "Order Business Rules and Client Scripts",
            "html": "<h2 id="std-order-business-rules-and-client-scripts">Order Business Rules and Client Scripts</h2>
<p>When more than one Business Rule runs at the same timing on the same table, the <strong>Order</strong> field decides the sequence - the lowest number runs first, and the default is 100. Order matters the moment one rule depends on what another just did. If a <em>before</em> rule sets <code>current.assignment_group</code> and a second <em>before</em> rule reads that group to pick an approver, the rule that sets the value must have the lower Order - otherwise the second rule runs first and reads an empty field.</p>
<p>Leave gaps between the numbers - 100, 200, 300 rather than 1, 2, 3 - so you can slot a new rule between two existing ones later without renumbering the rest.</p>
<p>And resist spreading one piece of order-dependent logic across many small rules just because you can. A chain of five rules that must fire in an exact sequence is hard to reason about, and a single changed Order number breaks it silently. When steps are tightly coupled, keep them together in one rule - or in one Script Include the rule calls - where the order is simply the order of the lines.</p>
<p>Client Scripts have the same lever, with one catch: their <strong>Order</strong> field isn't on the form by default, so add it before you rely on it. The rule is identical - lower runs first - so when one onLoad or onChange script depends on a value another sets, give the script that sets it the lower Order.</p>"
          },
          {
            "id": "run-only-whats-needed",
            "title": "Run Only What's Needed",
            "html": "<h2 id="std-run-only-whats-needed">Run Only What's Needed</h2>
<p>Because Business Rules run on every insert, update, delete, or query to their table, always give them a condition. The condition is evaluated first; the script runs only if it passes. Without one, the rule executes for every operation on the table - more work, and harder to debug, since you can no longer tell at a glance which rules should have fired. Set the condition in the <strong>Filter Conditions</strong> (or <strong>Condition</strong>) field, not in the script.</p>
<p>Client Scripts have no condition field, so an <code>onLoad</code> or <code>onChange</code> script runs in full every time the form loads. Do only necessary work, and add guards early. Starting from an inefficient handler that looks up the CI's support group on every change:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">onChange</span>(control, oldValue, newValue, isLoading) {
  <span class="c-kw">var</span> ciSupportGroup = g_form.<span class="c-fn">getReference</span>(<span class="c-str">'cmdb_ci'</span>).support_group;

  <span class="c-kw">if</span> (ciSupportGroup &amp;&amp; g_form.<span class="c-fn">getValue</span>(<span class="c-str">'assignment_group'</span>)) {
    g_form.<span class="c-fn">setValue</span>(<span class="c-str">'assignment_group'</span>, ciSupportGroup.sys_id);
  }
}</code></pre>
<p>layer in the standard guards, cheapest first, so the expensive server call happens as rarely as possible:</p>
<pre class="std-pre"><code><span class="c-kw">function</span> <span class="c-fn">onChange</span>(control, oldValue, newValue, isLoading, isTemplate) {
  <span class="c-com">// isLoading: nothing to do on form load - the logic already ran when the field last changed</span>
  <span class="c-kw">if</span> (isLoading) {
    <span class="c-kw">return</span>;
  }

  <span class="c-com">// newValue: skip when the field was cleared</span>
  <span class="c-kw">if</span> (!newValue) {
    <span class="c-kw">return</span>;
  }

  <span class="c-com">// only react to an actual change</span>
  <span class="c-kw">if</span> (newValue === oldValue) {
    <span class="c-kw">return</span>;
  }

  <span class="c-com">// check what the client already knows before calling the server</span>
  <span class="c-kw">if</span> (g_form.<span class="c-fn">getValue</span>(<span class="c-str">'assignment_group'</span>)) {
    <span class="c-kw">return</span>;
  }

  <span class="c-kw">var</span> glideAjax = <span class="c-kw">new</span> <span class="c-fn">GlideAjax</span>(<span class="c-str">'ConfigurationItem'</span>);

  glideAjax.<span class="c-fn">addParam</span>(<span class="c-str">'sysparm_name'</span>, <span class="c-str">'getSupportGroup'</span>);
  glideAjax.<span class="c-fn">addParam</span>(<span class="c-str">'sysparm_ci'</span>, g_form.<span class="c-fn">getValue</span>(<span class="c-str">'cmdb_ci'</span>));

  glideAjax.<span class="c-fn">getXMLAnswer</span>(<span class="c-kw">function</span> (response) {
    g_form.<span class="c-fn">setValue</span>(<span class="c-str">'assignment_group'</span>, response);
  });
}</code></pre>
<p>Two related habits: prefer a <strong>UI Policy</strong> to a Client Script when you only need to make a field mandatory, read-only, or visible - no script required. And remember that UI Policies and Client Scripts apply to forms only; to keep the same rules in a list, disable list editing, add an access control or data policy, or write an <code>onCellEdit</code> Client Script.</p>"
          }
        ]
      },
      {
        "title": "Avoid Common Pitfalls",
        "group": "Principles",
        "lead": "<p>A handful of specific mistakes cause an outsized share of hard-to-trace defects. Learn to spot them.</p>",
        "sections": [
          {
            "id": "do-not-use-hard-coded-values",
            "title": "Do Not Use Hard-Coded Values",
            "html": "<h2 id="std-do-not-use-hard-coded-values">Do Not Use Hard-Coded Values</h2>
<p>Hard-coded values produce unpredictable behavior and are hard to track down. sys_ids are the worst offenders - they differ between instances, so a value copied from a dev instance will not exist in production:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> taskId = <span class="c-str">'26c811f06075388068d07268c841dcd0'</span>;
<span class="c-kw">var</span> groupName = <span class="c-str">'Service Desk'</span>;</code></pre>
<p>Look the value up, or store it in a system property and read it with <code>gs.getProperty()</code>:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> taskId = gs.<span class="c-fn">getProperty</span>(<span class="c-str">'acme.default.task'</span>);
<span class="c-kw">var</span> groupName = gs.<span class="c-fn">getProperty</span>(<span class="c-str">'acme.group.name'</span>);</code></pre>
<p>Hard-coded names cause the same trouble the moment the organization changes. If a workflow needs approval from the IT director and you hard-code that person, you rewrite the workflow every time the role changes hands. Instead, create an <strong>IT Director</strong> group, use a Group Approval activity, and change group membership when the role changes - the workflow never moves.</p>"
          },
          {
            "id": "avoid-dot-walking-to-a-references-sysid",
            "title": "Avoid Dot-Walking to a Reference's sys_id",
            "html": "<h2 id="std-avoid-dot-walking-to-a-references-sysid">Avoid Dot-Walking to a Reference's sys_id</h2>
<p>A reference field's value already <em>is</em> a sys_id, so dot-walking to <code>.sys_id</code> forces an extra database query to load the referenced record and read it back:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> id = current.caller_id.sys_id;</code></pre>
<p>Read the field directly:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> id = current.<span class="c-fn">getValue</span>(<span class="c-str">'caller_id'</span>);</code></pre>"
          },
          {
            "id": "use-getdisplayvalue-effectively",
            "title": "Use getDisplayValue() Effectively",
            "html": "<h2 id="std-use-getdisplayvalue-effectively">Use getDisplayValue() Effectively</h2>
<p>Do not hard-code the display field's name (<code>number</code>, <code>name</code>, and so on); use <code>getDisplayValue()</code>. Naming the field couples your code to a dictionary setting that can change:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> parent = current.parent.number;
<span class="c-kw">var</span> myCi = current.cmdb_ci.name;</code></pre>
<p>If someone changes the display field on the Configuration Item table from <code>name</code> to <code>serial_number</code>, the second line is now wrong. Ask for the display value and the platform gives you whatever the current display field is:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> parent = current.<span class="c-fn">getDisplayValue</span>(<span class="c-str">'parent'</span>);
<span class="c-kw">var</span> myCi = current.<span class="c-fn">getDisplayValue</span>(<span class="c-str">'cmdb_ci'</span>);</code></pre>"
          },
          {
            "id": "set-fields-with-setvalue-and-setdisplayvalue",
            "title": "Set Fields with setValue() and setDisplayValue()",
            "html": "<h2 id="std-set-fields-with-setvalue-and-setdisplayvalue">Set Fields with setValue() and setDisplayValue() <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>Set fields the same deliberate way you read them - with <code>setValue()</code>, the write-side counterpart to <code>getValue()</code> - rather than assigning the field directly. Direct assignment leans on an auto-setter that blurs the line between a field's stored value and its display value, and can mishandle typed fields like dates, durations, and references. <code>setValue()</code> is explicit and type-safe:</p>
<pre class="std-pre"><code><span class="c-com">// fragile - relies on the auto-setter:</span>
current.state = <span class="c-num">3</span>;

<span class="c-com">// explicit and type-safe:</span>
current.<span class="c-fn">setValue</span>(<span class="c-str">'state'</span>, <span class="c-num">3</span>);</code></pre>
<p>When what you have is the <em>display</em> value rather than the stored value - a choice label, or a reference by its name - use <code>setDisplayValue()</code> and let the platform resolve it to the underlying value:</p>
<pre class="std-pre"><code><span class="c-com">// set a reference field from the record's display name, not its sys_id:</span>
current.<span class="c-fn">setDisplayValue</span>(<span class="c-str">'assigned_to'</span>, <span class="c-str">'Fred Luddy'</span>);</code></pre>
<p>The same idea applies on the client through <code>g_form.setValue()</code> - and when the field is a reference, pass the display value alongside the sys_id to avoid a round trip (see Minimize Server Lookups).</p>"
          },
          {
            "id": "avoid-dom-manipulation",
            "title": "Avoid DOM Manipulation",
            "html": "<h2 id="std-avoid-dom-manipulation">Avoid DOM Manipulation</h2>
<p>Avoid manipulating the DOM directly - it breaks when browsers update, and referencing an out-of-box element by id or CSS selector breaks when that element's id or position changes. Use the GlideForm (<code>g_form</code>) API instead, or rethink the approach. The only place DOM work is defensible is where you own the DOM: UI Pages and the Service Portal.</p>"
          },
          {
            "id": "work-in-stages",
            "title": "Work in Stages",
            "html": "<h2 id="std-work-in-stages">Work in Stages</h2>
<p>Do not write hundreds of lines in one sitting, especially while learning something new - write a little, test it, and continue. It feels slower, but tracing a defect through a small increment beats hunting through a large one.</p>
<p>And prove out new ideas in a sandbox, not a shared development instance. Experimenting inside an update set risks promoting unwanted changes; experimenting outside one can leave your development instance behaving unlike the others. If you have no sandbox, use a ServiceNow demo instance, then build the real thing in development once you understand the approach.</p>"
          }
        ]
      },
      {
        "title": "Enforce Security",
        "group": "Principles",
        "lead": "<p>Access control is the platform's job - until you write a line of server code, where you can either step around it or become it. Both directions deserve care: code that reads data on a user's behalf should respect what that user is allowed to see, and an access rule you write runs on every record it guards.</p>",
        "sections": [
          {
            "id": "keep-acl-scripts-fast",
            "title": "Keep ACL Scripts Fast",
            "html": "<h2 id="std-keep-acl-scripts-fast">Keep ACL Scripts Fast <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>An ACL script evaluates every time someone reads, writes, or even sees a record or field it protects - and on a list, that is once per row, per column. A cheap check costs nothing noticeable; a GlideRecord query inside the script is paid on every one of those evaluations and quietly tanks list performance. Keep an ACL script to in-memory checks - roles, and values already on the current record - and have it set <code>answer</code> to a boolean:</p>
<pre class="std-pre"><code><span class="c-com">// runs on every record this rule guards - keep it cheap, no queries</span>
answer = gs.<span class="c-fn">hasRole</span>(<span class="c-str">'incident_manager'</span>) || current.<span class="c-fn">getValue</span>(<span class="c-str">'assigned_to'</span>) === gs.<span class="c-fn">getUserID</span>();</code></pre>
<p>If a rule genuinely needs data from another table, resolve it once and cache it rather than querying inside the ACL itself.</p>"
          },
          {
            "id": "enforce-acls-in-server-code-with-gliderecordsecure",
            "title": "Enforce ACLs in Server Code with GlideRecordSecure",
            "html": "<h2 id="std-enforce-acls-in-server-code-with-gliderecordsecure">Enforce ACLs in Server Code with GlideRecordSecure <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>A plain <code>new GlideRecord()</code> runs with full rights and ignores access controls entirely. That is correct for trusted background logic, but dangerous the moment your code acts on behalf of a user - a client-callable Script Include answering a GlideAjax call, or a Scripted REST resource. There, use <code>GlideRecordSecure</code>, which enforces the same ACLs the user would hit in the UI, so your code cannot hand back records they were never allowed to see:</p>
<pre class="std-pre"><code><span class="c-com">// honors the caller's ACLs - they get only the records they are permitted to read</span>
<span class="c-kw">var</span> incidentGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecordSecure</span>(<span class="c-str">'incident'</span>);

incidentGr.<span class="c-fn">addQuery</span>(<span class="c-str">'active'</span>, <span class="c-kw">true</span>);
incidentGr.<span class="c-fn">query</span>();</code></pre>
<p>The rule of thumb: GlideRecord for trusted server-to-server work, GlideRecordSecure whenever a user's request is driving the query.</p>"
          },
          {
            "id": "back-reference-qualifiers-with-a-script-include",
            "title": "Back Reference Qualifiers with a Script Include",
            "html": "<h2 id="std-back-reference-qualifiers-with-a-script-include">Back Reference Qualifiers with a Script Include <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>An advanced reference qualifier decides which records a reference field is allowed to offer. Written inline on the dictionary entry, that logic is hard to test, impossible to reuse, and easy to lose. Move it into a Script Include that returns an encoded query and point the qualifier at it - the same "extract shared logic, load it only when called" reasoning behind preferring Script Includes to global scripts.</p>
<p>The <code>AssignmentGroup</code> Script Include shown earlier already returns exactly the right shape - a <code>sys_idIN…</code> string of the groups a user belongs to. A reference qualifier can call it directly:</p>
<pre class="std-pre"><code>javascript: <span class="c-kw">new</span> <span class="c-fn">AssignmentGroup</span>().<span class="c-fn">backfillAssignmentGroup</span>()</code></pre>
<p>Now the field offers only valid groups, the logic lives in one testable place, and it loads only when that field is actually shown.</p>"
          }
        ]
      },
      {
        "title": "Write UI Actions Well",
        "group": "Build It Well",
        "lead": "<p>A UI Action is the button or link a user clicks on a form or list. It can run on the client, on the server, or hand off from one to the other - and choosing the right side, showing it only when it makes sense, and telling the user what happened are what separate a solid button from a confusing one.</p>",
        "sections": [
          {
            "id": "choose-client-or-server",
            "title": "Choose Client or Server",
            "html": "<h2 id="std-choose-client-or-server">Choose Client or Server <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>A <strong>server</strong> UI Action runs a script with <code>current</code> and <code>action</code> after the click - use it to change records and redirect. A <strong>client</strong> UI Action (the <em>Client</em> checkbox, with an <code>onclick</code> handler) runs in the browser with <code>g_form</code> and never touches the server on its own - use it for confirmation dialogs and form validation that should happen before anything is submitted.</p>
<p>Match the side to the work. Validation the browser can do needs no server round trip:</p>
<pre class="std-pre"><code><span class="c-com">// Client UI Action - runs in the browser with g_form</span>
<span class="c-kw">function</span> <span class="c-fn">validateAndSubmit</span>() {
  <span class="c-kw">if</span> (!g_form.<span class="c-fn">getValue</span>(<span class="c-str">'short_description'</span>)) {
    g_form.<span class="c-fn">addErrorMessage</span>(<span class="c-str">'Enter a short description first.'</span>);
    <span class="c-kw">return</span> <span class="c-kw">false</span>;
  }

  g_form.<span class="c-fn">save</span>();
}</code></pre>
<p>Work that changes records belongs on the server, where it runs with <code>current</code>:</p>
<pre class="std-pre"><code><span class="c-com">// Server UI Action - runs with current and action</span>
current.<span class="c-fn">setValue</span>(<span class="c-str">'state'</span>, <span class="c-num">3</span>);
current.<span class="c-fn">update</span>();

gs.<span class="c-fn">addInfoMessage</span>(<span class="c-str">'Incident closed.'</span>);
action.<span class="c-fn">setRedirectURL</span>(current); <span class="c-com">// send the user back to the saved record</span></code></pre>"
          },
          {
            "id": "always-give-a-ui-action-a-condition",
            "title": "Always Give a UI Action a Condition",
            "html": "<h2 id="std-always-give-a-ui-action-a-condition">Always Give a UI Action a Condition <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>The <strong>Condition</strong> field decides when the button or link appears. Leave it blank and the action shows for everyone, on every record, whether or not it could possibly apply - clutter at best, a confusing dead end at worst. Set the condition declaratively, the same way a Business Rule gets one, so the platform hides the action when it does not apply instead of the script running and bailing out:</p>
<pre class="std-pre"><code>gs.<span class="c-fn">hasRole</span>(<span class="c-str">'incident_manager'</span>) &amp;&amp; current.active</code></pre>"
          },
          {
            "id": "redirect-and-respond-deliberately",
            "title": "Redirect and Respond Deliberately",
            "html": "<h2 id="std-redirect-and-respond-deliberately">Redirect and Respond Deliberately <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>After a server UI Action does its work, tell the user what happened. <code>action.setRedirectURL()</code> sends them somewhere sensible - back to the saved record, on to a related list, or to a landing page - and <code>gs.addInfoMessage()</code> (or <code>addErrorMessage()</code>) confirms the outcome. Skipping both leaves the user on a stale form wondering whether the click did anything.</p>"
          },
          {
            "id": "reach-for-declarative-first",
            "title": "Reach for Declarative First",
            "html": "<h2 id="std-reach-for-declarative-first">Reach for Declarative First <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>Before writing a UI Action at all, ask whether it needs a script. If the goal is to set a field, flip a state, or show and hide controls, a UI Policy or a Flow often does it with no code to maintain - and the less script there is, the less there is to break when the form or the requirement changes.</p>"
          }
        ]
      },
      {
        "title": "Run Server Code Safely",
        "group": "Build It Well",
        "lead": "<p>Code that runs unattended - on a schedule, once across a whole table, or in a background window with full rights - has no user watching to catch a mistake, and often no undo. That earns it extra care: bound what it touches, make it safe to re-run, and prove it somewhere disposable first.</p>",
        "sections": [
          {
            "id": "scheduled-jobs",
            "title": "Scheduled Jobs",
            "html": "<h2 id="std-scheduled-jobs">Scheduled Jobs <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>A Scheduled Job runs a script on a timer, unattended. Its danger is scale: a job that loops every matching record can hold resources for a long time and slow the instance for everyone. Bound the work - process a capped batch per run, or filter to only the records that still need attention - and let a later run pick up the rest, rather than trying to finish an unbounded set in one pass. When the job's real work can happen out of band, fire an event and let the event queue carry the load (see below) so the job itself returns quickly.</p>"
          },
          {
            "id": "fix-scripts",
            "title": "Fix Scripts",
            "html": "<h2 id="std-fix-scripts">Fix Scripts <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>A Fix Script is a one-time data change, run once when its update set is committed to an instance. Two habits make it safe. Make it <strong>idempotent</strong> - safe to run twice - by checking state before it writes, so a re-run or a partial failure does not double-apply. And have it <strong>log what it touched</strong> so you can confirm afterward exactly what changed:</p>
<pre class="std-pre"><code><span class="c-kw">var</span> updated = <span class="c-num">0</span>;
<span class="c-kw">var</span> incidentGr = <span class="c-kw">new</span> <span class="c-fn">GlideRecord</span>(<span class="c-str">'incident'</span>);

incidentGr.<span class="c-fn">addQuery</span>(<span class="c-str">'category'</span>, <span class="c-str">'inquiry'</span>);
incidentGr.<span class="c-fn">addQuery</span>(<span class="c-str">'subcategory'</span>, <span class="c-str">''</span>); <span class="c-com">// only the ones not already fixed - keeps a re-run safe</span>
incidentGr.<span class="c-fn">query</span>();

<span class="c-kw">while</span> (incidentGr.<span class="c-fn">next</span>()) {
  incidentGr.<span class="c-fn">setValue</span>(<span class="c-str">'subcategory'</span>, <span class="c-str">'general'</span>);
  incidentGr.<span class="c-fn">update</span>();
  updated++;
}

gs.<span class="c-fn">info</span>(<span class="c-str">'Fix: set default subcategory on '</span> + updated + <span class="c-str">' inquiry incidents'</span>);</code></pre>
<p>Run it against a sub-production copy first and confirm the count matches what you expected before you promote it.</p>"
          },
          {
            "id": "background-scripts",
            "title": "Background Scripts",
            "html": "<h2 id="std-background-scripts">Background Scripts <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>The <strong>Scripts - Background</strong> module runs whatever you paste, immediately, against the instance you are on, with full rights and no undo. It is the right tool for a quick read or a one-off check - and the wrong place to try anything destructive in production. While you are developing, add <code>setLimit()</code> so a runaway query cannot touch more than you meant, read before you write, and if you want the change to travel to other instances, put it in a Fix Script instead so it is captured, reviewable, and repeatable.</p>"
          },
          {
            "id": "events-and-script-actions",
            "title": "Events and Script Actions",
            "html": "<h2 id="std-events-and-script-actions">Events and Script Actions <span class="std-source-badge" title="Beyond GlideFast's original three guides">Extended guidance</span></h2>
<p>When something happens that should trigger extra work - notify a team, sync an external system - do not make the user's transaction wait for it. Hand the work to the event queue with <code>gs.eventQueue()</code>; a Script Action (or the notification engine) picks the event up out of band, so the click returns to the user immediately and the follow-on work runs asynchronously:</p>
<pre class="std-pre"><code><span class="c-com">// in a Business Rule - queue the work and return; the Script Action does the rest</span>
gs.<span class="c-fn">eventQueue</span>(<span class="c-str">'incident.escalated'</span>, current, current.<span class="c-fn">getValue</span>(<span class="c-str">'assigned_to'</span>), priorityLabel);</code></pre>
<p>This is the reusable, decoupled cousin of an async Business Rule: many producers can fire the same event, and one Script Action handles it in one place.</p>"
          }
        ]
      }
    ]
  };

  return {
    DOC: DOC,
  };
}

['$rootScope', '$timeout', 'StandardsService', '$sce', function ($rootScope, $timeout, StandardsService, $sce) {
  'use strict';

  // Plain-text search corpus for a section: strips tags from its rendered HTML (which already
  // includes the title inside its <h2>, so this alone covers both) and lowercases once here rather
  // than per keystroke/digest.
  function stripHtml(html) {
    var div = document.createElement('div');
    div.innerHTML = html;
    return (div.textContent || div.innerText || '').toLowerCase();
  }

  // Mirrors build-standards.js's own slugify() so chapter/band ids read the same way section ids
  // do. Computed client-side (not via that script's registerSlug/duplicate-checked registry) - the
  // 'chapter-'/'band-' prefixes below are what actually guarantee no collision with a real section
  // slug, not this function's uniqueness on its own.
  function slugify(title) {
    return String(title).toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-');
  }

  // The combined GlideFast scripting standards, hosted in-app (see StandardsService - a generated
  // provider built from standards/glidefast-scripting-standards.md). Trusted ONCE here into a stable
  // structure - ng-bind-html re-evaluates per digest, so handing it a fresh trustAsHtml() result
  // each time would never settle.
  var doc = {
    lead: $sce.trustAsHtml(StandardsService.DOC.lead),
    parts: StandardsService.DOC.parts.map(function (part) {
      return {
        // 'chapter-' prefix: a chapter title (e.g. "Choose Client or Server") could otherwise
        // slugify to something a section heading also plausibly uses - the prefix keeps this id
        // namespace disjoint from section ids without needing build-standards.js's slug registry.
        id: 'chapter-' + slugify(part.title),
        title: part.title,
        group: part.group,
        lead: $sce.trustAsHtml(part.lead),
        sections: part.sections.map(function (section) {
          return { id: section.id, title: section.title, html: $sce.trustAsHtml(section.html), searchText: stripHtml(section.html) };
        }),
      };
    }),
  };
  // A grouped VIEW of the same parts, for the rail/content bands (see index.html) - doc.parts
  // stays flat and untouched for anything that still wants to walk every chapter directly. Order
  // here is the display order of the bands; must match build-standards.js's VALID_GROUPS keys.
  var GROUP_ORDER = ['Principles', 'Build It Well'];
  // Chapters known to be coming but not written yet - shown as dashed "Planned" tiles in the
  // Contents hub (index.html's .std-hub) so the roadmap is visible instead of the band just
  // looking thin. Plain strings, not real parts - no id/lead/sections, nothing to click through
  // to. Edit this list as chapters land (remove here) or as new ones are planned (add here); it
  // has no other effect on the doc.
  var PLANNED_BY_GROUP = {
    'Build It Well': ['Flows', 'Widgets', 'CSS', 'Portals', 'UI Builder'],
  };
  doc.groups = GROUP_ORDER.map(function (name) {
    return {
      name: name,
      id: 'band-' + slugify(name),
      parts: doc.parts.filter(function (p) { return p.group === name; }),
      planned: PLANNED_BY_GROUP[name] || [],
    };
  }).filter(function (g) { return g.parts.length > 0; });

  // Hand-rolled scrollTop animation, not the browser's native `scrollTo({behavior:'smooth'})`/
  // `el.scrollIntoView({behavior:'smooth'})` - both were tried first and silently no-op when issued
  // right after this pane's ng-if just rendered ~50KB of new DOM (scrollTop stayed 0). Driving
  // scrollTop directly every frame is the exact mechanism that already reliably works in that
  // situation (a plain assignment does), just spread across frames with easing instead of one
  // instant jump. Kept deliberately quick (200-450ms) - a fast, confident hop reads calmer than a
  // slow one. Respects prefers-reduced-motion the same way the rest of this app's CSS transitions/
  // animations already do (see the global override in app.scss).
  function animateScrollTop(pane, targetTop, onDone) {
    var startTop = pane.scrollTop;
    var delta = targetTop - startTop;
    var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (Math.abs(delta) < 2 || reduced) {
      pane.scrollTop = targetTop;
      if (onDone) { onDone(); }
      return;
    }
    var duration = Math.min(450, Math.max(200, Math.abs(delta) * 0.15));
    var startTime = null;
    function step(timestamp) {
      if (startTime === null) { startTime = timestamp; }
      var progress = Math.min((timestamp - startTime) / duration, 1);
      var eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic - fast start, gentle landing
      pane.scrollTop = startTop + delta * eased;
      if (progress < 1) { requestAnimationFrame(step); } else if (onDone) { onDone(); }
    }
    requestAnimationFrame(step);
  }

  // Scrolls to section `id` (called after the caller has already switched into Standards mode).
  // `enteringFresh` (arriving from another mode, not already browsing Standards) spotlights JUST the
  // target section once the scroll lands - onFocusChange(id) is how that's reported back, since
  // vm.stdFocusId lives on the controller, not here. Deliberately NOT engaged up front - only once
  // the scroll actually LANDS - so the page stays fully sharp while it scrolls and the focus dim
  // fades in only once the reader has actually arrived (engaging it up front used to mean the whole
  // page went dim+blurry for the full scroll).
  // While a programmatic scroll (a deep-link or a rail-link click) is animating, the scroll-spy is
  // suppressed so its intermediate - and at-bottom - positions don't drag the rail highlight off the
  // section the user actually picked. The controller sets vm.activeStdId to that section up front,
  // and this keeps it there until the scroll lands. It matters most near the bottom: those sections
  // can't reach the top-of-pane active band, so without this the spy would snap the highlight to the
  // last section the moment the click bottomed the pane out - the exact "last few links don't
  // highlight when clicked" symptom.
  var spySuppressed = false;
  function scrollTo(id, enteringFresh, onFocusChange) {
    spySuppressed = true;
    $timeout(function () {
      var el = document.getElementById('std-' + id);
      var pane = document.querySelector('.builder');
      if (!el || !pane) { spySuppressed = false; return; }
      // 115px clearance: the sticky header's own footprint (59px, measured live) plus ~56px of
      // breathing room - landing any closer reads as the heading crowding the pinned header (91px/
      // ~32px of room was tried first and felt cramped, especially with the focus-mode Back/Stay
      // buttons occupying the same row).
      var top = Math.max(0, pane.scrollTop + el.getBoundingClientRect().top - pane.getBoundingClientRect().top - 115);
      animateScrollTop(pane, top, function () {
        spySuppressed = false; // scroll landed - let the spy track normal scrolling again
        $timeout(function () {
          if (enteringFresh) { onFocusChange(id); }
          el.classList.add('std-flash');
          $timeout(function () { el.classList.remove('std-flash'); }, 1600);
        });
      });
    }, 80);
  }

  // Overview rail item: scrolls the reading pane back to the top of the Contents card (the hub),
  // same easing as scrollTo() above - the reciprocal of "jump to a chapter."
  function scrollToTop() {
    var pane = document.querySelector('.builder');
    if (pane) { animateScrollTop(pane, 0); }
  }

  // The sticky "on this page" rail highlights whichever section is currently at the top of the
  // reading pane. One observer watches every section h2 (the same ids scrollTo() targets); torn down
  // whenever the reader leaves Standards so it doesn't keep firing against detached DOM.
  var observer = null;
  var scrollPane = null;
  var scrollHandler = null;
  function teardownScrollSpy() {
    if (observer) { observer.disconnect(); observer = null; }
    if (scrollPane && scrollHandler) { scrollPane.removeEventListener('scroll', scrollHandler); }
    scrollPane = null;
    scrollHandler = null;
  }
  // On the FIRST visit to Standards, the doc's ~25 ng-bind-html sections can still be mid-render when
  // this fires - retry with backoff rather than a single fixed delay, so a slow first paint doesn't
  // leave the rail permanently unhighlighted until the reader leaves and comes back.
  function setupScrollSpy(onActiveChange, attempt) {
    attempt = attempt || 0;
    teardownScrollSpy();
    var pane = document.querySelector('.builder');
    var heads = document.querySelectorAll('.standards-doc h2[id^="std-"]');
    if (!pane || !heads.length) {
      if (attempt < 5) { $timeout(function () { setupScrollSpy(onActiveChange, attempt + 1); }, 250); }
      return;
    }
    var lastId = heads[heads.length - 1].id.replace(/^std-/, '');
    function commit(id) { $rootScope.$applyAsync(function () { onActiveChange(id); }); }
    // The rootMargin below shrinks the observer's active band to the top of the pane, so a heading
    // only wins once it can be scrolled up there. The last sections physically can't reach it - the
    // pane bottoms out first - so at the very bottom the observer alone would keep an earlier section
    // lit, and the last few rail links never highlighted. atBottom() lets the bottom win instead,
    // guarded so a doc that doesn't overflow isn't treated as "at bottom" (which would wrongly light
    // the last section on a short page).
    function atBottom() {
      return pane.scrollHeight > pane.clientHeight + 4 &&
        pane.scrollTop + pane.clientHeight >= pane.scrollHeight - 4;
    }
    // Tracks every observed heading's OWN latest intersecting position (or null), updated
    // incrementally from each callback - NOT just whichever headings happen to appear in the current
    // batch. IntersectionObserver only reports elements whose state flipped since the last check, so
    // on a short section the next heading can enter the scroll-spy band in its OWN later batch,
    // containing just that one entry; picking the topmost from that batch alone (the old logic)
    // silently promoted it over a still-intersecting, still-topmost heading that simply wasn't
    // mentioned in this particular batch. Recomputing the topmost from the full known state every
    // time fixes that.
    var intersectingTops = {};
    observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        intersectingTops[e.target.id] = e.isIntersecting ? e.boundingClientRect.top : null;
      });
      if (spySuppressed) { return; }
      if (atBottom()) { commit(lastId); return; }
      var visible = Object.keys(intersectingTops)
        .filter(function (id) { return intersectingTops[id] !== null; })
        .map(function (id) { return { id: id, top: intersectingTops[id] }; });
      if (!visible.length) { return; }
      visible.sort(function (a, b) { return a.top - b.top; });
      commit(visible[0].id.replace(/^std-/, ''));
    }, { root: pane, rootMargin: '0px 0px -75% 0px', threshold: 0 });
    heads.forEach(function (h) { observer.observe(h); });
    // The observer only fires on intersection flips; scrolling the final pixels to the very bottom
    // may not cause one, so a scroll listener asserts the last section there directly.
    scrollPane = pane;
    scrollHandler = function () { if (spySuppressed) { return; } if (atBottom()) { commit(lastId); } };
    pane.addEventListener('scroll', scrollHandler, { passive: true });
  }

  return {
    doc: doc,
    scrollTo: scrollTo,
    scrollToTop: scrollToTop,
    setupScrollSpy: setupScrollSpy,
    teardownScrollSpy: teardownScrollSpy,
  };
}]

sp_widget.client_script:
api.controller = function ($scope, ThemeService, StandardsUiService) {
    'use strict';
    var vm = this;

    // App-wide light/dark toggle (see ThemeService) - persists to localStorage and applies
    // straight to documentElement. vm.theme is a thin display mirror the template reads; syncTheme
    // refreshes it after each toggle.
    // Init with this app's own key prefix so Standards keeps its independent stored theme choice
    // ('standardsPortalTheme').
    ThemeService.init('standardsPortal');
    function syncTheme() { vm.theme = ThemeService.readState().theme; }
    syncTheme();
    vm.toggleTheme = function () { ThemeService.toggleApp(); syncTheme(); };

    /* ============================= Standards (hosted document) ============================= */
    // The document itself, and the deep-link-scroll/scroll-spy mechanics, live in
    // StandardsUiService - passed straight through (vm.standardsDoc is built once and never
    // reassigned, so this one-time reference copy is safe).
    vm.standardsDoc = StandardsUiService.doc;
    // Two views sharing one mounted DOM: 'overview' (the Contents card's chapter hub, doc hidden) vs
    // 'reading' (the doc visible, hub hidden) - see .std-reading-hidden in app.scss for why this is
    // a visibility toggle, not ng-if/ng-show. Starts on 'overview'; openStandard is the one place
    // that flips it to 'reading', since every path that lands on a specific chapter/section (a hub
    // tile, a rail link, or an external deep-link) already routes through it.
    vm.stdView = 'overview';
    // Search: filters the rail + reading pane down to matching sections via ng-show (NOT ng-if -
    // ng-if would destroy/recreate the <h2> nodes the scroll-spy's IntersectionObserver already
    // snapshotted, permanently desyncing it). Plain per-digest boolean predicates - cheap at this
    // doc's size (~40 sections), no memoization needed.
    vm.stdQuery = '';
    vm.stdSectionMatches = function (section) {
      var q = vm.stdQuery.trim().toLowerCase();
      return !q || section.searchText.indexOf(q) !== -1;
    };
    vm.stdPartVisible = function (part) {
      return !vm.stdQuery.trim() || part.sections.some(vm.stdSectionMatches);
    };
    vm.stdGroupVisible = function (grp) {
      return !vm.stdQuery.trim() || grp.parts.some(vm.stdPartVisible);
    };
    vm.stdHasMatches = function () { return vm.standardsDoc.groups.some(vm.stdGroupVisible); };
    vm.clearStdSearch = function () { vm.stdQuery = ''; };
    // The chapter BUTTON's own highlight - exact id match only (the chapter heading itself, not any
    // section under it). Once the reader has drilled into a specific section, that section carries
    // its own highlight (.std-rail-section.active in index.html) instead.
    vm.stdPartHeadingActive = function (part) { return vm.activeStdId === part.id; };
    // Per-chapter expand/collapse for the rail's section sub-list - purely manual, keyed by part.id
    // (plain object, not part of vm.standardsDoc - this is rail UI state, not doc data). The ONLY
    // way this changes is vm.toggleStdExpand, wired to the chevron alone (index.html) - navigating
    // to a chapter or section, or typing a search, never touches this map.
    vm.stdExpanded = {};
    vm.stdPartExpanded = function (part) { return !!vm.stdExpanded[part.id]; };
    vm.toggleStdExpand = function (part, $event) {
      if ($event) { $event.stopPropagation(); }
      vm.stdExpanded[part.id] = !vm.stdExpanded[part.id];
    };
    // Navigates to a chapter/section id (a hub tile, a rail link, or an external deep-link all
    // route through this).
    vm.openStandard = function (id) {
      vm.stdView = 'reading';
      // Highlight the picked section in the rail immediately; StandardsUiService.scrollTo
      // suppresses the scroll-spy through the scroll so it can't snap the highlight elsewhere
      // before landing.
      vm.activeStdId = id;
      StandardsUiService.scrollTo(id, false, function () {});
    };
    // Rail's pinned "Overview" item - the reciprocal of openStandard: hides the doc, shows the hub.
    vm.showStdOverview = function () {
      vm.stdView = 'overview';
      vm.activeStdId = null;
      StandardsUiService.scrollToTop();
    };
    vm.activeStdId = null;
    // The sticky rail's scroll-spy runs for the app's whole lifetime - there is no other page to
    // leave it for, so unlike a multi-page app's mode-driven setup/teardown, this fires once.
    StandardsUiService.setupScrollSpy(function (id) { if (vm.stdView === 'reading') { vm.activeStdId = id; } });
  },;

sp_widget.css:
/* GlideFast Standards Portal - visual identity: card-based layout, light/dark theming, and
   Standards-page (.std-*) treatment, trimmed to only what this standalone doc viewer needs (no
   builder forms, no output pane, no sidenav/mode-switcher).

   SCSS SOURCE, not hand-edited CSS - css/app.css is a BUILD OUTPUT (npx sass scss/app.scss
   css/app.css --no-source-map). Edit this file, not that one.

   Color tokens stay real SCSS variables with `!default` so a future ServiceNow deploy (see
   scripts/build-deploy.js) can ship them as a Theme's actual CSS Variables and have this file's
   content ship as a CSS Include that references them uncompiled. */// ---------- Light (default) palette ----------
$gs-bg: #f4f5f7 !default;
$gs-panel: #ffffff !default;
$gs-panel-alt: #fbfbfd !default;
$gs-border: #e2e5ea !default;
$gs-border-strong: #d2d6dd !default;
$gs-text: #1c2128 !default;
$gs-muted: #6b7280 !default;
$gs-faint: #9aa1ab !default;
$gs-accent: #054b80 !default;
$gs-accent-hover: #043a63 !default;
$gs-accent-soft: #e6eef5 !default;
$gs-accent-soft-hover: #d6e6f2 !default;
$gs-accent-border: #b3cae0 !default;// Topbar background - the brand navy the source app used for its sidenav; this app has no// sidenav, just a slim top bar, but keeps the same brand color for it.
$gs-topbar-bg: #054b80 !default;

$gs-purple: #6d3fc9 !default;
$gs-purple-soft: #f1ecfb !default;
$gs-purple-border: #d3c2ee !default;
$gs-green: #15803d !default;
$gs-green-soft: #e8f5ec !default;
$gs-green-border: #bfe3cb !default;// Code-sample palette - the doc's <pre> blocks use a generated-script-style highlighter look// (.c-kw/.c-str/.c-num/.c-com/.c-fn). Bound directly to these $gs-ed-* values (not var(--...)) per// app THEME - see the .std-pre rule below for why.
$gs-ed-bg: #ffffff !default;
$gs-ed-text: #1c2128 !default;
$gs-ed-border: #e2e5ea !default;
$gs-ed-kw: #8250df !default;
$gs-ed-str: #116329 !default;
$gs-ed-num: #953800 !default;
$gs-ed-com: #6b7280 !default;
$gs-ed-fn: #0550ae !default;

$gs-ed-bg-dark: #1b1f2a !default;
$gs-ed-text-dark: #e6e9ef !default;
$gs-ed-border-dark: #2c3242 !default;
$gs-ed-kw-dark: #c792ea !default;
$gs-ed-str-dark: #c3e88d !default;
$gs-ed-num-dark: #f78c6c !default;
$gs-ed-com-dark: #5a6275 !default;
$gs-ed-fn-dark: #82aaff !default;// ---------- Dark palette ----------
$gs-bg-dark: #10131a !default;
$gs-panel-dark: #1a1f29 !default;
$gs-panel-alt-dark: #20262f !default;
$gs-border-dark: #2a3040 !default;
$gs-border-strong-dark: #3b4353 !default;
$gs-text-dark: #e7ebf2 !default;
$gs-muted-dark: #9aa3b6 !default;
$gs-faint-dark: #6b7385 !default;
$gs-accent-dark: #5b9fe0 !default;
$gs-accent-hover-dark: #7ab3ea !default;
$gs-accent-soft-dark: rgba(91, 159, 224, 0.16) !default;
$gs-accent-soft-hover-dark: rgba(91, 159, 224, 0.28) !default;
$gs-accent-border-dark: rgba(91, 159, 224, 0.4) !default;
$gs-topbar-bg-dark: #043962 !default;
$gs-purple-dark: #b79cf0 !default;
$gs-purple-soft-dark: rgba(183, 156, 240, 0.16) !default;
$gs-purple-border-dark: rgba(183, 156, 240, 0.4) !default;
$gs-green-dark: #6ee7a0 !default;
$gs-green-soft-dark: rgba(110, 231, 160, 0.14) !default;
$gs-green-border-dark: rgba(110, 231, 160, 0.36) !default;.gfsp-widget {
  --bg: #{$gs-bg};
  --panel: #{$gs-panel};
  --panel-alt: #{$gs-panel-alt};
  --border: #{$gs-border};
  --border-strong: #{$gs-border-strong};
  --text: #{$gs-text};
  --muted: #{$gs-muted};
  --faint: #{$gs-faint};
  --accent: #{$gs-accent};
  --accent-hover: #{$gs-accent-hover};
  --accent-soft: #{$gs-accent-soft};
  --accent-soft-hover: #{$gs-accent-soft-hover};
  --accent-border: #{$gs-accent-border};
  --topbar-bg: #{$gs-topbar-bg};
  --ed-bg: #{$gs-ed-bg};
  --ed-text: #{$gs-ed-text};
  --ed-border: #{$gs-ed-border};
  --ed-kw: #{$gs-ed-kw};
  --ed-str: #{$gs-ed-str};
  --ed-num: #{$gs-ed-num};
  --ed-com: #{$gs-ed-com};
  --ed-fn: #{$gs-ed-fn};
  --radius: 10px;
  --radius-sm: 7px;
  --shadow: 0 1px 2px rgba(16,24,40,.06), 0 1px 3px rgba(16,24,40,.10);
  --sp-xxs: 2px;
  --sp-xs:  4px;
  --sp-sm:  8px;
  --sp-md:  12px;
  --sp-lg:  16px;
  --sp-xl:  20px;
  --sp-xxl: 24px;
  --font: 'Montserrat', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: "SF Mono", "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;
  --purple: #{$gs-purple};
  --purple-soft: #{$gs-purple-soft};
  --purple-border: #{$gs-purple-border};
  --green: #{$gs-green};
  --green-soft: #{$gs-green-soft};
  --green-border: #{$gs-green-border};
}/* Dark mode. `data-theme` is set on <html> by vm.toggleTheme() (see ThemeService) - overriding the
   custom properties here is enough to re-theme every component that already references
   var(--...) instead of a literal color; the handful that don't (the .std-pre code-sample surface)
   get their own explicit :root[data-theme="dark"] overrides further down, same as the source app. */.gfsp-widget[data-theme="dark"] {
  --bg: #{$gs-bg-dark};
  --panel: #{$gs-panel-dark};
  --panel-alt: #{$gs-panel-alt-dark};
  --border: #{$gs-border-dark};
  --border-strong: #{$gs-border-strong-dark};
  --text: #{$gs-text-dark};
  --muted: #{$gs-muted-dark};
  --faint: #{$gs-faint-dark};
  --accent: #{$gs-accent-dark};
  --accent-hover: #{$gs-accent-hover-dark};
  --accent-soft: #{$gs-accent-soft-dark};
  --accent-soft-hover: #{$gs-accent-soft-hover-dark};
  --accent-border: #{$gs-accent-border-dark};
  --topbar-bg: #{$gs-topbar-bg-dark};
  --shadow: 0 1px 2px rgba(0,0,0,.24), 0 1px 3px rgba(0,0,0,.32);
  --purple: #{$gs-purple-dark};
  --purple-soft: #{$gs-purple-soft-dark};
  --purple-border: #{$gs-purple-border-dark};
  --green: #{$gs-green-dark};
  --green-soft: #{$gs-green-soft-dark};
  --green-border: #{$gs-green-border-dark};
}/* ---------- Base reset ---------- */.gfsp-widget * { box-sizing: border-box; }// Angular's built-in ngCloak directive strips the ng-cloak attribute once it compiles the element// that carries it, but the HIDING has to come from plain CSS (not JS) - this rule is what keeps// raw, not-yet-compiled markup off the screen during the gap between the browser parsing the// static HTML and Angular (loaded from a CDN) finishing bootstrap..gfsp-widget [ng-cloak] { display: none !important; }/* Animates the light/dark toggle: vm.toggleTheme() just flips the data-theme attribute, which
   changes every var(--...) custom property at once - transitioning the few concrete properties
   that actually consume them is what makes that swap read as a fade instead of a hard cut. */.gfsp-widget *, .gfsp-widget *::before, .gfsp-widget *::after {
  transition: background-color .22s ease, color .22s ease, border-color .22s ease, box-shadow .22s ease, fill .22s ease, stroke .22s ease;
}@media (prefers-reduced-motion: reduce) {.gfsp-widget *, .gfsp-widget *::before, .gfsp-widget *::after { transition: none !important; animation: none !important; }
}.gfsp-widget [hidden] { display: none !important; }.gfsp-widget, .gfsp-widget { height: 100%; }.gfsp-widget {
  margin: 0;
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  font-size: 13.5px;
  -webkit-font-smoothing: antialiased;
}.gfsp-widget .card { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); margin-bottom: var(--sp-lg); overflow: hidden; }.gfsp-widget .card-head { display: flex; align-items: center; justify-content: space-between; padding: var(--sp-md) var(--sp-lg); border-bottom: 1px solid var(--border); }.gfsp-widget .card-head h2 { margin: 0; font-size: 12px; font-weight: 650; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }.gfsp-widget .card-body { padding: var(--sp-md) var(--sp-lg); }.gfsp-widget .hint { font-size: 11.5px; color: var(--muted); margin: 0 0 var(--sp-md); line-height: 1.5; }.gfsp-widget .empty { font-size: 12px; color: var(--faint); font-style: italic; padding: var(--sp-xs) 0; }.gfsp-widget input[type=text] {
  width: 100%; height: 34px; padding: 0 var(--sp-md);
  border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  background: var(--panel); font: inherit; font-size: 13px; color: var(--text);
  transition: border-color .12s, box-shadow .12s;
}.gfsp-widget input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }.gfsp-widget input::placeholder { color: var(--faint); }/* ---------- App shell ---------- */// No sidenav/mode-switcher (this app is nothing but the Standards page) - just a slim brand bar// pinned above the scrolling content pane..gfsp-widget .app { display: flex; flex-direction: column; height: 100vh; }.gfsp-widget .topbar {
  flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
  gap: var(--sp-md); padding: var(--sp-sm) var(--sp-lg);
  background: var(--topbar-bg);
}.gfsp-widget .topbar-brand { display: flex; align-items: center; gap: var(--sp-sm); font-weight: 650; font-size: 13px; color: #fff; white-space: nowrap; }.gfsp-widget .topbar-logo { width: 26px; height: 26px; border-radius: 7px; background: rgba(255,255,255,.16); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 13px; color: #fff; flex-shrink: 0; }.gfsp-widget .topbar-theme-toggle {
  display: flex; align-items: center; justify-content: center;
  width: 30px; height: 30px; flex-shrink: 0; padding: 0;
  border: 1px solid rgba(255,255,255,.25); border-radius: var(--radius-sm);
  background: rgba(255,255,255,.12); color: #fff; cursor: pointer; transition: background .12s, border-color .12s;
}.gfsp-widget .topbar-theme-toggle:hover { background: rgba(255,255,255,.2); border-color: rgba(255,255,255,.4); }// The scrolling content pane - StandardsUiService.scrollTo/scrollToTop/setupScrollSpy all query// `.builder` by class name for this element, so the name is kept even though there's no other// builder pane left to distinguish it from..gfsp-widget .builder { flex: 1; min-height: 0; overflow-y: auto; overflow-anchor: none; padding: 0 var(--sp-xl) 80px; }.gfsp-widget .page-title { display: flex; align-items: flex-start; gap: var(--sp-md); margin: 0 0 var(--sp-xxl); padding-top: var(--sp-xl); }.gfsp-widget .page-title > span:first-child { display: flex; color: var(--accent); }.gfsp-widget .page-title-name { font-size: 20px; font-weight: 650; color: var(--text); line-height: 1.1; }.gfsp-widget .page-title-sub { font-size: 12.5px; font-weight: 500; color: var(--muted); margin-top: var(--sp-xxs); }.gfsp-widget .page-title-actions { margin-left: auto; align-self: center; display: flex; gap: var(--sp-sm); flex-wrap: wrap; justify-content: flex-end; }// Sticky header - stays reachable (title + search) while scrolled, since the doc runs far longer// than one screen. Background covers its own padding-top so nothing peeks through above it while// pinned (see the source app's own comment on this rule for the layout gotcha that requires it)..gfsp-widget .page-title-sticky { position: sticky; top: 0; z-index: 5; background: var(--bg); }// Below this, the title text plus the search box's fixed 220px width no longer fit on one row -// wrap the search onto its own row rather than letting it run off the right edge (the fixed// std-search-wrap-header width was measured against a desktop-width header, not a phone one).@media (max-width: 560px) {.gfsp-widget .page-title { flex-wrap: wrap; }.gfsp-widget .page-title-actions { margin-left: 0; width: 100%; justify-content: flex-start; }.gfsp-widget .std-search-wrap-header .std-search-input { width: 100%; }
}/* ---------- Standards page (hosted GlideFast best-practices document) ---------- */// Rendered from StandardsService's pre-parsed HTML (see scripts/build-standards.js). Two-column// layout: the reading column caps at .std-content's measure (940px) rather than stretching to// fill the pane, and a sticky rail uses the reclaimed width for an "on this page" nav..gfsp-widget .standards-doc { display: flex; align-items: flex-start; gap: var(--sp-xxl); max-width: 1204px; margin: 0 auto; }.gfsp-widget .std-doc-main { flex: 1; min-width: 0; max-width: 940px; position: relative; overflow: hidden; }// Keeps a .std-band genuinely laid out (never display:none) while Overview is showing, so// StandardsUiService.scrollTo's getBoundingClientRect() measurement is always accurate the instant// a tile/rail-link is clicked - display:none was tried first and caused a real, reproduced bug// (a large layout-cost first reveal made the very next scrollTo land short)..gfsp-widget .std-reading-hidden { position: absolute; top: 0; left: 0; width: 100%; visibility: hidden; pointer-events: none; }.gfsp-widget .std-rail {
  width: 240px; flex-shrink: 0; align-self: flex-start;
  position: sticky; top: 75px;
  max-height: calc(100vh - 75px - var(--sp-xl));
  overflow-y: auto; padding: 0 var(--sp-sm) var(--sp-lg);
}.gfsp-widget .std-rail-overview {
  display: block; width: 100%; text-align: left; border: 0; border-left: 2px solid transparent; background: transparent; cursor: pointer;
  font: inherit; font-size: 12.5px; font-weight: 700; color: var(--muted);
  padding: var(--sp-xs) 0 var(--sp-xs) var(--sp-sm); margin-left: -1px; margin-bottom: var(--sp-lg);
  transition: color .12s, border-color .12s;
}.gfsp-widget .std-rail .std-search-wrap {
  position: sticky; top: 0; z-index: 1; background: var(--bg);
  margin-bottom: var(--sp-md);
}.gfsp-widget .std-rail .std-search-wrap .std-search-input { width: 100%; }.gfsp-widget .std-rail-overview:hover { color: var(--text); }.gfsp-widget .std-rail-overview.active { color: var(--accent); border-left-color: var(--accent); }.gfsp-widget .std-rail-band + .std-rail-band { margin-top: var(--sp-xl); }.gfsp-widget .std-rail-band-title {
  display: block; width: 100%; text-align: left; border: 0; border-left: 2px solid transparent; background: transparent; cursor: pointer;
  font: inherit; font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: .05em;
  color: var(--text); margin-left: -1px; margin-bottom: var(--sp-sm);
}.gfsp-widget .std-rail-band-title:hover { color: var(--accent); }.gfsp-widget .std-rail-chapter { margin-bottom: 2px; }.gfsp-widget .std-rail-part-row { display: flex; align-items: stretch; }.gfsp-widget .std-rail-part {
  flex: 1; min-width: 0; text-align: left; border: 0; background: transparent;
  border-left: 2px solid transparent; margin-left: -1px;
  padding: 3px 0 3px var(--sp-sm); cursor: pointer; font: inherit; font-size: 12px; line-height: 1.5;
  color: var(--muted);
}.gfsp-widget .std-rail-part:hover { color: var(--text); }.gfsp-widget .std-rail-part.active { color: var(--accent); border-left-color: var(--accent); font-weight: 600; letter-spacing: -0.02em; }.gfsp-widget .std-rail-expand {
  flex-shrink: 0; display: flex; align-items: center; justify-content: center;
  width: 20px; border: 0; background: transparent; border-radius: var(--radius-sm);
  color: var(--faint); cursor: pointer; padding: 0;
  transition: color .12s, background .12s;
}.gfsp-widget .std-rail-expand svg { transition: transform .15s; }.gfsp-widget .std-rail-expand.expanded svg { transform: rotate(90deg); }.gfsp-widget .std-rail-expand:hover { color: var(--text); background: var(--panel-alt); }.gfsp-widget .std-rail-sections { margin-bottom: 2px; }.gfsp-widget .std-rail-section {
  display: block; width: 100%; text-align: left; border: 0; background: transparent;
  border-left: 2px solid transparent; margin-left: -1px;
  padding: 2px 0 2px var(--sp-lg); cursor: pointer; font: inherit; font-size: 11.5px; line-height: 1.6;
  color: var(--faint);
}.gfsp-widget .std-rail-section:hover { color: var(--text); }.gfsp-widget .std-rail-section.active { color: var(--accent); border-left-color: var(--accent); font-weight: 600; }// Below this, .std-doc-main alone (940px) plus padding doesn't leave enough room for a 240px// rail without cramping the reading column - the rail is the ONLY in-page nav, so below this// width the reader falls back to plain scrolling.@media (max-width: 1260px) {.gfsp-widget .std-rail { display: none; }
}.gfsp-widget .std-link {
  border: 0; background: transparent; padding: 0; cursor: pointer;
  font: inherit; font-weight: 600; color: var(--accent); white-space: nowrap;
}.gfsp-widget .std-link:hover { text-decoration: underline; }.gfsp-widget .std-band + .std-band { margin-top: var(--sp-xxl); }.gfsp-widget .std-band-heading {
  font-size: 20px; font-weight: 800; text-transform: uppercase; letter-spacing: .03em;
  color: var(--text); margin: 0 0 var(--sp-lg);
}// Standards search box - lives in the sticky .page-title so it stays reachable regardless of// scroll position or viewport width, unlike the Contents card it started in or the TOC rail// (which hides below 1260px). The clear "x" sits INSIDE the input's own box, not as a flex// sibling, so typing a query never widens the row..gfsp-widget .std-search-wrap { position: relative; display: flex; align-items: center; }.gfsp-widget .std-search-wrap .std-search-input { width: 220px; padding-right: 26px; }.gfsp-widget .std-search-clear {
  position: absolute; right: 6px; top: 50%; transform: translateY(-50%);
  display: flex; align-items: center; justify-content: center;
  width: 18px; height: 18px; padding: 0; border: 0; border-radius: var(--radius-sm);
  background: transparent; color: var(--muted); cursor: pointer; font-size: 11px; line-height: 1;
}.gfsp-widget .std-search-clear:hover { color: var(--text); background: var(--panel-alt); }// The rail carries its own search box, but it hides below 1260px - the header keeps a second copy// (.std-search-wrap-header) as the sole fallback below that width; hidden here whenever the// rail's own copy is on-screen so exactly one of the two ever renders.@media (min-width: 1261px) {.gfsp-widget .std-search-wrap-header { display: none; }
}.gfsp-widget .std-content { font-size: 13px; line-height: 1.65; color: var(--text); max-width: 940px; }.gfsp-widget .std-content h2 { font-size: 16px; font-weight: 650; margin: var(--sp-xxl) 0 var(--sp-sm); }.gfsp-widget .std-content h3 { font-size: 13.5px; font-weight: 650; margin: var(--sp-xl) 0 var(--sp-sm); }.gfsp-widget .std-content h2:first-child, .gfsp-widget .std-content > div > h2:first-child { margin-top: var(--sp-sm); }.gfsp-widget .std-content h2, .gfsp-widget .std-content h3 { scroll-margin-top: var(--sp-lg); }.gfsp-widget .std-content p { margin: 0 0 var(--sp-md); }.gfsp-widget .std-content ul, .gfsp-widget .std-content ol { margin: 0 0 var(--sp-md); padding-left: 22px; }.gfsp-widget .std-content li { margin-bottom: var(--sp-xxs); }.gfsp-widget .std-content code {
  font-family: var(--mono); font-size: 12px;
  background: var(--panel-alt); border: 1px solid var(--border); border-radius: 4px; padding: 1px 5px;
}.gfsp-widget .std-content a { color: var(--accent); text-decoration: underline; text-underline-offset: 2px; }.gfsp-widget .std-content a:hover { color: var(--accent-hover); }// Code samples use the generated-script highlighter's .c-* token spans (see the .c-* rules// below), bound to the editor palette per APP theme so a snippet in the doc stays legible in// both themes..gfsp-widget .std-pre {
  margin: 0 0 var(--sp-md); padding: var(--sp-md) var(--sp-lg); overflow-x: auto;
  font-family: var(--mono); border-radius: var(--radius-sm);
  background: #{$gs-ed-bg}; border: 1px solid #{$gs-ed-border};
}.gfsp-widget .std-pre code { background: transparent; border: 0; padding: 0; font-size: 12.5px; line-height: 1.6; color: #{$gs-ed-text}; }.gfsp-widget[data-theme="dark"] .std-pre { background: #{$gs-ed-bg-dark}; border-color: #{$gs-ed-border-dark}; }.gfsp-widget[data-theme="dark"] .std-pre code { color: #{$gs-ed-text-dark}; }.gfsp-widget .c-kw { color: var(--ed-kw); }.gfsp-widget .c-str { color: var(--ed-str); }.gfsp-widget .c-num { color: var(--ed-num); }.gfsp-widget .c-com { color: var(--ed-com); font-style: italic; }.gfsp-widget .c-fn { color: var(--ed-fn); }.gfsp-widget[data-theme="dark"] .std-content .c-kw { color: #{$gs-ed-kw-dark}; }.gfsp-widget[data-theme="dark"] .std-content .c-str { color: #{$gs-ed-str-dark}; }.gfsp-widget[data-theme="dark"] .std-content .c-num { color: #{$gs-ed-num-dark}; }.gfsp-widget[data-theme="dark"] .std-content .c-com { color: #{$gs-ed-com-dark}; }.gfsp-widget[data-theme="dark"] .std-content .c-fn { color: #{$gs-ed-fn-dark}; }.gfsp-widget .std-source-badge {
  display: inline-flex; align-items: center;
  margin-left: var(--sp-sm); vertical-align: middle;
  border: 1px solid var(--border); background: var(--panel-alt); color: var(--muted);
  border-radius: var(--radius-sm); padding: 2px var(--sp-sm);
  font-size: 10.5px; font-weight: 650; letter-spacing: .02em; text-transform: uppercase;
}.gfsp-widget .std-table { border-collapse: collapse; margin: 0 0 var(--sp-md); width: 100%; }.gfsp-widget .std-table th, .gfsp-widget .std-table td { border: 1px solid var(--border); padding: var(--sp-xs) var(--sp-md); text-align: left; vertical-align: top; }.gfsp-widget .std-table th { background: var(--panel-alt); font-weight: 650; }.gfsp-widget .std-hub { margin-top: var(--sp-xl); }.gfsp-widget .std-hub-band + .std-hub-band { margin-top: var(--sp-xl); }.gfsp-widget .std-hub-band-title {
  font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .05em;
  color: var(--faint); margin: 0 0 var(--sp-md);
}.gfsp-widget .std-hub-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: var(--sp-md); }.gfsp-widget .std-hub-tile {
  display: flex; flex-direction: column; gap: var(--sp-xxs); text-align: left;
  border: 1px solid var(--border); border-radius: var(--radius); background: var(--panel);
  padding: var(--sp-md); font: inherit; cursor: pointer; transition: border-color .12s, box-shadow .12s;
}.gfsp-widget .std-hub-tile:hover { border-color: var(--accent-border); box-shadow: var(--shadow); }.gfsp-widget .std-hub-tile:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }.gfsp-widget .std-hub-tile .ic { display: block; width: 15px; height: 15px; margin-bottom: 2px; color: var(--accent); }.gfsp-widget .std-hub-tile-alt .ic { color: var(--purple); }.gfsp-widget .std-hub-tile.ghost .ic { color: var(--faint); }.gfsp-widget .std-hub-tile .t { font-size: 12.5px; font-weight: 650; color: var(--text); line-height: 1.35; }.gfsp-widget .std-hub-tile .meta { font-size: 10.5px; color: var(--faint); }.gfsp-widget .std-hub-tile.ghost { border-style: dashed; cursor: default; opacity: .7; }.gfsp-widget .std-hub-tile.ghost:hover { border-color: var(--border); box-shadow: none; }.gfsp-widget .std-hub-tile .badge {
  align-self: flex-start; margin-top: 2px; font-size: 9px; font-weight: 700; letter-spacing: .04em;
  text-transform: uppercase; color: var(--faint); background: var(--panel-alt); border: 1px solid var(--border-strong);
  border-radius: 20px; padding: 2px 7px;
}// Deep-link landing flash - marks WHICH heading a rail/hub link pointed at (targets are often// mid-page). Animation, not a transition, so the reduced-motion override above still kills it..gfsp-widget @keyframes stdFlash {
  0% { background: var(--accent-soft); box-shadow: 0 0 0 6px var(--accent-soft); }
  100% { background: transparent; box-shadow: 0 0 0 6px transparent; }
}.gfsp-widget .std-flash { animation: stdFlash 1.5s ease-out; border-radius: var(--radius-sm); }

sp_widget.script:
(function() {
  /* No server-side data needed - the document and its UI mechanics all live in the injected Angular services. */
})();
